// CONFIGURAZIONE
// Legge i parametri dalle variabili d'ambiente (docker-compose.yml / .env).
// Nessun valore e' scritto nel workflow: chi lo esegue su un'altra macchina
// cambia solo il file .env.
const numero = (v, predefinito) =>
  v === undefined || v === null || v === '' || isNaN(Number(v)) ? predefinito : Number(v);

if (!$env.OPENAI_API_KEY) {
  throw new Error('OPENAI_API_KEY mancante: copia .env.example in .env e inserisci la chiave');
}

return [{
  json: {
    input_file: $env.INPUT_FILE || '/files/input/ritz_carlton_reviews.csv',
    // contesto del dominio: chi e' recensito, chi legge, categorie di segnalazione
    context_file: $env.CONTEXT_FILE || '/files/contesto/contesto.json',
    output_dir: ($env.OUTPUT_DIR || '/files/output').replace(/\/+$/, ''),
    model: $env.LLM_MODEL || 'gpt-4.1-mini',
    base_url: ($env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/+$/, ''),
    // 0 = tutte le recensioni; un numero > 0 = campione deterministico per le prove
    limit: numero($env.LIMIT, 0),
    // recensioni per chiamata al modello nell'analisi
    batch_size: numero($env.BATCH_SIZE, 5),
    // recensioni lette per far emergere gli aspetti
    discovery_sample: numero($env.DISCOVERY_SAMPLE, 240),
    // minimo di recensioni per periodo nell'andamento nel tempo
    min_reviews_per_period: numero($env.MIN_REVIEWS_PER_PERIOD, 100),
    // elenco fisso degli aspetti: se il file esiste si usa quello e la scoperta
    // degli aspetti si salta; RISCOPRI_ASPETTI=true forza una nuova scoperta
    aspects_file: $env.ASPECTS_FILE || '/files/aspetti/aspetti_fissi.json',
    riscopri_aspetti: String($env.RISCOPRI_ASPETTI || '').toLowerCase() === 'true',
    // minimo di menzioni per entrare nelle classifiche "per tasso"
    min_mentions_rate_ranking: numero($env.MIN_MENTIONS_RATE_RANKING, 30),
    // prezzi del modello in dollari per milione di token (listino da verificare quando cambia)
    prezzo_input_usd_per_milione: numero($env.PREZZO_INPUT_USD_PER_MILIONE, 0.4),
    prezzo_output_usd_per_milione: numero($env.PREZZO_OUTPUT_USD_PER_MILIONE, 1.6),
    seed: 42,
    started_at: new Date().toISOString(),
  },
}];

// VALIDA IL CONTESTO DEL DOMINIO
// Il contesto (data/contesto/contesto.json) dice al sistema che cosa viene
// recensito, chi scrive, chi legge i risultati, in che lingua scrivere il digest
// e quali problemi vanno segnalati. Tutti i prompt lo leggono da qui: per
// passare da un hotel a un'app o a un negozio si cambia solo quel file.
// Il contesto NON suggerisce aspetti: quelli emergono dalle recensioni.
const c = $input.first().json.data ?? $input.first().json;
const errori = [];
const testo = (campo) => {
  const v = String(c[campo] ?? '').trim();
  if (!v) errori.push(`manca "${campo}"`);
  return v;
};

const ctx = {
  oggetto_recensito: testo('oggetto_recensito'),
  descrizione: testo('descrizione'),
  autori_delle_recensioni: testo('autori_delle_recensioni'),
  lettori_dei_risultati: testo('lettori_dei_risultati'),
  lingua_del_digest: testo('lingua_del_digest'),
  critiche_ordinarie_da_non_segnalare: String(c.critiche_ordinarie_da_non_segnalare ?? '').trim(),
};

const v = c.voto ?? {};
ctx.voto = {
  minimo: Number(v.minimo ?? 1),
  massimo: Number(v.massimo ?? 5),
  basso_fino_a: Number(v.basso_fino_a ?? 2),
  alto_da: Number(v.alto_da ?? 4),
};
if (!(ctx.voto.minimo < ctx.voto.basso_fino_a && ctx.voto.basso_fino_a < ctx.voto.alto_da && ctx.voto.alto_da <= ctx.voto.massimo)) {
  errori.push('scala del voto non coerente: serve minimo < basso_fino_a < alto_da <= massimo');
}

ctx.categorie = {};
for (const [codice, cat] of Object.entries(c.categorie_di_segnalazione ?? {})) {
  if (!/^[a-z][a-z0-9_]*$/.test(codice)) errori.push(`codice di categoria non valido: "${codice}" (solo minuscole, cifre e _)`);
  if (!['alta', 'media'].includes(cat?.priorita)) errori.push(`categoria "${codice}": priorita deve essere "alta" o "media"`);
  if (!String(cat?.nome ?? '').trim() || !String(cat?.definizione ?? '').trim()) errori.push(`categoria "${codice}": servono nome e definizione`);
  ctx.categorie[codice] = { nome: String(cat?.nome ?? codice).trim(), priorita: cat?.priorita, definizione: String(cat?.definizione ?? '').trim() };
}
if (Object.keys(ctx.categorie).length === 0) errori.push('servono almeno una categoria di segnalazione');

if (errori.length) throw new Error('File di contesto non valido:\n- ' + errori.join('\n- '));

// frase di contesto riusata in tutti i prompt
ctx.frase = `Context: the texts are reviews of ${ctx.oggetto_recensito}, written by ${ctx.autori_delle_recensioni}. ${ctx.descrizione} The results are read by ${ctx.lettori_dei_risultati}.`;
return [{ json: ctx }];

// ASSEGNA ID E PULISCI
// Ogni recensione riceve un identificativo stabile che dipende solo dal suo
// contenuto: review_id = "R" + primi 10 caratteri di sha1(publishedDate|title|text).
// Se il file viene riordinato o ricaricato, gli identificativi non cambiano.
// Qui si controllano anche i campi e si annotano le anomalie (rumore del file).
const crypto = require('crypto');
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;

const pulisci = (s) => String(s ?? '').replace(/\r\n?/g, '\n').trim();
const sha1 = (s) => crypto.createHash('sha1').update(s, 'utf8').digest('hex');

const righe = $input.all().map((i) => i.json);
if (righe.length === 0) throw new Error('Nessuna recensione nel file ' + cfg.input_file);
for (const c of ['title', 'rating', 'publishedDate', 'text']) {
  if (!(c in righe[0])) throw new Error('Colonna mancante nel CSV: ' + c);
}

const visti = new Set();
const anomalie = [];
let recensioni = righe.map((r, i) => {
  const riga = i + 2; // la riga 1 del file e' l'intestazione
  const title = pulisci(r.title);
  const text = pulisci(r.text);
  const published = pulisci(r.publishedDate);
  const travelGrezzo = pulisci(r.travelDate);

  const h = sha1([published, title, text].join('|'));
  let id = 'R' + h.slice(0, 10);
  let duplicato_di = null;
  if (visti.has(id)) {
    // stessa data, stesso titolo, stesso testo: duplicato esatto
    duplicato_di = id;
    let k = 2;
    while (visti.has(`${id}-${k}`)) k++;
    id = `${id}-${k}`;
    anomalie.push({ riga, review_id: id, tipo: 'duplicato', dettaglio: 'uguale a ' + duplicato_di });
  }
  visti.add(id);

  const n = Number(pulisci(r.rating));
  const rating = Number.isInteger(n) && n >= ctx.voto.minimo && n <= ctx.voto.massimo ? n : null;
  if (rating === null) anomalie.push({ riga, review_id: id, tipo: 'voto_non_valido', dettaglio: String(r.rating ?? '') });

  const dataOk = /^\d{4}-\d{2}-\d{2}$/.test(published) && !isNaN(Date.parse(published));
  if (!dataOk) anomalie.push({ riga, review_id: id, tipo: 'data_pubblicazione_non_valida', dettaglio: published });

  let travel = /^\d{4}-\d{2}$/.test(travelGrezzo) ? travelGrezzo : null;
  if (!travelGrezzo) anomalie.push({ riga, review_id: id, tipo: 'data_soggiorno_mancante', dettaglio: null });
  else if (!travel) anomalie.push({ riga, review_id: id, tipo: 'data_soggiorno_non_valida', dettaglio: travelGrezzo });
  if (travel && dataOk && travel > published.slice(0, 7)) {
    anomalie.push({ riga, review_id: id, tipo: 'soggiorno_dopo_pubblicazione', dettaglio: `${travel} > ${published}` });
    travel = null;
  }

  // testo per il modello: spazi multipli ridotti, a capo mantenuti
  const testo = text.replace(/[ \t ]+/g, ' ').replace(/\n{3,}/g, '\n\n');
  const vuota = testo.length === 0 && title.length === 0;
  if (vuota) anomalie.push({ riga, review_id: id, tipo: 'recensione_vuota', dettaglio: null });
  else if (testo.length === 0) anomalie.push({ riga, review_id: id, tipo: 'testo_vuoto_si_usa_il_titolo', dettaglio: null });

  return {
    review_id: id,
    riga,
    ordine_hash: h.slice(10, 18), // ordine pseudo-casuale ma ripetibile
    title,
    text: testo,
    rating,
    published_date: dataOk ? published : null,
    travel_date: travel,
    anno: dataOk ? Number(published.slice(0, 4)) : null,
    duplicato_di,
    vuota,
  };
});

// ordine cronologico; le recensioni senza data valida in fondo
recensioni.sort(
  (a, b) => (a.published_date ?? '9999').localeCompare(b.published_date ?? '9999') || a.review_id.localeCompare(b.review_id),
);

// LIMIT > 0: campione ripetibile per le prove (ordine dato dall'hash, quindi sparso negli anni)
if (cfg.limit > 0 && cfg.limit < recensioni.length) {
  const scelti = new Set(
    [...recensioni].sort((a, b) => a.ordine_hash.localeCompare(b.ordine_hash)).slice(0, cfg.limit).map((r) => r.review_id),
  );
  recensioni = recensioni.filter((r) => scelti.has(r.review_id));
}

// le informazioni sul file viaggiano sul primo elemento
recensioni[0] = { ...recensioni[0], _file: { righe_nel_file: righe.length, anomalie } };
return recensioni.map((r) => ({ json: r }));

// PREPARA IL CONTROLLO DELLA MANIPOLAZIONE (memoria del guardrail, 16/11)
// Il guardrail «manipolazione» chiama il modello una volta per recensione: con 2.300 recensioni era la parte
// che faceva durare il giro mezz'ora. Qui si mandano al guardrail solo le recensioni NUOVE o CAMBIATE.
// Per le altre l'esito si riprende dalla memoria (memoria_guardrail.json nella cartella dei risultati), se la
// «firma» e' la stessa: impronta della configurazione del guardrail (istruzioni, espressioni regolari, soglia:
// calcolata da build_workflow.py e scritta qui sotto), del modello e del testo gia' ripulito dai dati personali.
// Cambia una di queste cose -> il controllo si rifa'. Le recensioni con un errore tecnico del guardrail non
// vanno in memoria: si ricontrollano al giro dopo. Il nodo «Recensioni pronte» rimette insieme gli esiti.
const crypto = require('crypto');
const FIRMA_CONFIGURAZIONE = '428a21ad1a79aa26556bc5eb73061e0ba18405f9';
const modello = $env.GUARDRAIL_MODEL || 'gpt-4.1-mini';
const firma = (testo) => crypto.createHash('sha1').update(JSON.stringify([FIRMA_CONFIGURAZIONE, modello, testo]), 'utf8').digest('hex');
const originali = $('Assegna ID e pulisci').all().map((i) => i.json);
const puliti = $('Guardrail: dati sensibili').all();
let memoria = {};
try {
  memoria = $('Estrai memoria guardrail').first().json.data?.voci ?? {};
} catch (e) {
  memoria = {};
}
const out = [];
puliti.forEach((it, i) => {
  const testo = String(it.json.guardrailsInput ?? '');
  const m = memoria[originali[i]?.review_id];
  if (m && m.firma === firma(testo)) return; // gia' controllata con la stessa configurazione e lo stesso testo
  out.push({ json: { guardrailsInput: testo, indice_originale: i } });
});
// niente di nuovo: un testo neutro, cosi' il guardrail (e il resto del giro) parte comunque; il suo esito si ignora
if (!out.length) out.push({ json: { guardrailsInput: 'ok', indice_originale: null } });
return out;

// RECENSIONI PRONTE (dopo i guardrail di ingresso)
// Rimette insieme ogni recensione con:
// - il testo ripulito dal guardrail "dati sensibili" (email, telefoni, carte,
//   IBAN, IP, chiavi e link sostituiti da segnaposto come <EMAIL_ADDRESS>):
//   da qui in poi il modello vede SOLO il testo ripulito;
// - l'esito del guardrail "manipolazione": le recensioni che contengono
//   istruzioni rivolte a un sistema automatico vengono marcate come sospette.
//   Si analizzano lo stesso (lo schema di risposta limita cio' che il modello
//   puo' restituire), ma vengono segnalate e tenute fuori dai conteggi.
const SEPARATORE = '\n§§§\n';
const originali = $('Assegna ID e pulisci').all().map((i) => i.json);
const puliti = $('Guardrail: dati sensibili').all();
if (puliti.length !== originali.length) {
  throw new Error(`Il guardrail dati sensibili ha restituito ${puliti.length} recensioni su ${originali.length}`);
}

// il guardrail riceve solo le recensioni nuove o cambiate (nodo «Prepara controllo manipolazione»): la posizione
// di ogni suo esito si riporta alla posizione della recensione con indice_originale
const inviate = $('Prepara controllo manipolazione').all().map((i) => i.json.indice_originale);
const indice = (it) => {
  const p = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  return inviate[p?.item] ?? null;
};
const esito = new Map();
for (const it of $('Guardrail: manipolazione').all(0)) {
  const i = indice(it);
  if (i !== null) esito.set(i, { sospetta: false, checks: it.json.checks ?? [] });
}
for (const it of $('Guardrail: manipolazione').all(1)) {
  // un errore tecnico del guardrail non rende sospetta la recensione
  const i = indice(it);
  if (i === null) continue;
  const errore = it.json.error ?? null;
  esito.set(i, { sospetta: !errore, errore, checks: it.json.checks ?? [] });
}
// le altre: esito dalla memoria (stessa firma del nodo «Prepara controllo manipolazione»)
const crypto = require('crypto');
const FIRMA_CONFIGURAZIONE = '428a21ad1a79aa26556bc5eb73061e0ba18405f9';
const modello = $env.GUARDRAIL_MODEL || 'gpt-4.1-mini';
const firma = (testo) => crypto.createHash('sha1').update(JSON.stringify([FIRMA_CONFIGURAZIONE, modello, testo]), 'utf8').digest('hex');
let memoria = {};
try {
  memoria = $('Estrai memoria guardrail').first().json.data?.voci ?? {};
} catch (e) {
  memoria = {};
}

const SEGNAPOSTO = /<([A-Z_]+)>/g;
return originali.map((r, i) => {
  const testoPulito = String(puliti[i].json.guardrailsInput ?? '');
  const pos = testoPulito.indexOf(SEPARATORE);
  const title = pos >= 0 ? testoPulito.slice(0, pos) : r.title;
  const text = pos >= 0 ? testoPulito.slice(pos + SEPARATORE.length) : testoPulito;
  const oscurati = {};
  for (const m of testoPulito.matchAll(SEGNAPOSTO)) oscurati[m[1]] = (oscurati[m[1]] ?? 0) + 1;
  const f = firma(testoPulito);
  const m = memoria[r.review_id];
  let sospetta, scattati, errore, dallaMemoria = false;
  if (esito.has(i)) {
    const e = esito.get(i);
    sospetta = e.sospetta;
    scattati = e.checks.filter((c) => c.triggered).map((c) => c.name);
    errore = e.errore ?? null;
  } else if (m && m.firma === f) {
    sospetta = !!m.sospetta;
    scattati = m.scattati ?? [];
    errore = null;
    dallaMemoria = true;
  } else {
    sospetta = false;
    scattati = [];
    errore = 'esito mancante';
  }
  return {
    json: {
      ...r,
      title,
      text,
      dati_oscurati: oscurati,
      sospetta,
      guardrail_scattati: scattati,
      guardrail_errore: errore,
      guardrail_firma: f,
      guardrail_dalla_memoria: dallaMemoria,
    },
  };
});

// CAMPIONE PER LA SCOPERTA DEGLI ASPETTI
// Gli aspetti non sono dati: emergono dalle recensioni in due passi.
// Passo 1 (qui e nel nodo LLM successivo): su un campione, il modello elenca
// liberamente i temi su cui l'ospite esprime un giudizio.
// Passo 2 (nodo "LLM - consolida aspetti"): i temi liberi, con la loro
// frequenza, vengono raggruppati in un elenco chiuso di aspetti.
//
// Il campione e' stratificato per voto: le recensioni con voto basso sono
// poche ma contengono le critiche che la direzione deve conoscere, quindi
// sono sovra-rappresentate (30% del campione). Dentro ogni strato l'ordine
// e' dato dall'hash dell'identificativo: pseudo-casuale ma ripetibile.
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;
const recensioni = $('Recensioni pronte')
  .all()
  .map((i) => i.json)
  .filter((r) => !r.vuota && !r.duplicato_di && !r.sospetta);

const strato = (r) => (r.rating === null ? 'senza_voto' : r.rating <= ctx.voto.basso_fino_a ? 'basso' : r.rating < ctx.voto.alto_da ? 'medio' : 'alto');
const quote = { basso: 0.3, medio: 0.25, alto: 0.45 };
const N = Math.min(cfg.discovery_sample, recensioni.length);

const perStrato = {};
for (const r of recensioni) (perStrato[strato(r)] ??= []).push(r);
for (const g of Object.values(perStrato)) g.sort((a, b) => a.ordine_hash.localeCompare(b.ordine_hash));

const campione = [];
for (const [s, q] of Object.entries(quote)) campione.push(...(perStrato[s] ?? []).slice(0, Math.round(N * q)));
if (campione.length < N) {
  // uno strato troppo piccolo: si completa con le altre recensioni in ordine di hash
  const presi = new Set(campione.map((r) => r.review_id));
  const resto = recensioni
    .filter((r) => !presi.has(r.review_id))
    .sort((a, b) => a.ordine_hash.localeCompare(b.ordine_hash));
  campione.push(...resto.slice(0, N - campione.length));
}

const SYSTEM = `${ctx.frase}
For each review, list every specific topic on which the author expresses an evaluation (positive, negative or neutral).
Rules:
- A topic is a concrete theme the author judges (for example a service, a feature, a cost, the behaviour of staff).
- Use a short English label of 1 to 3 words, generic and reusable across reviews. Not a sentence, no adjectives of judgement in the label.
- Do not list topics that are only mentioned without any evaluation.
- Do not use "overall experience" or the reviewed business itself as topics: the overall judgement is not a topic.
- Reviews can be in any language; labels are always in English.
- review_id must be copied exactly.`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['review_id', 'topics'],
        properties: {
          review_id: { type: 'string' },
          topics: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['label', 'sentiment'],
              properties: {
                label: { type: 'string' },
                sentiment: { type: 'string', enum: ['positive', 'negative', 'neutral'] },
              },
            },
          },
        },
      },
    },
  },
};

// nella scoperta i testi molto lunghi si tagliano a 2.500 caratteri (solo qui, non nell'analisi)
const payload = (r) => ({ review_id: r.review_id, title: r.title, text: r.text.slice(0, 2500) });
const GRUPPO = 10;
const richieste = [];
for (let i = 0; i < campione.length; i += GRUPPO) {
  const gruppo = campione.slice(i, i + GRUPPO);
  richieste.push({
    json: {
      ids: gruppo.map((r) => r.review_id),
      body: {
        model: cfg.model,
        temperature: 0,
        seed: cfg.seed,
        max_tokens: 4000,
        response_format: { type: 'json_schema', json_schema: { name: 'topics', strict: true, schema: SCHEMA } },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: JSON.stringify(gruppo.map(payload)) },
        ],
      },
    },
  });
}
return richieste;

// RACCOGLI I TEMI LIBERI E PREPARA IL CONSOLIDAMENTO
// Conta quante recensioni del campione citano ogni tema libero e con quale
// giudizio. La lista ordinata per frequenza va al modello, che la raggruppa
// in un elenco chiuso di aspetti.
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;

const normalizza = (s) =>
  String(s ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9 &/-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const conteggi = new Map();
let risposteNonValide = 0;
let recensioniLette = 0;
for (const it of $input.all()) {
  const content = it.json?.choices?.[0]?.message?.content;
  let dati = null;
  try {
    dati = JSON.parse(content);
  } catch (e) {
    risposteNonValide++;
    continue;
  }
  for (const r of dati.results ?? []) {
    recensioniLette++;
    const giaVisti = new Set(); // un tema conta una volta per recensione
    for (const t of r.topics ?? []) {
      const label = normalizza(t.label);
      if (!label || giaVisti.has(label)) continue;
      giaVisti.add(label);
      const c = conteggi.get(label) ?? { label, recensioni: 0, positive: 0, negative: 0, neutral: 0 };
      c.recensioni++;
      if (['positive', 'negative', 'neutral'].includes(t.sentiment)) c[t.sentiment]++;
      conteggi.set(label, c);
    }
  }
}
if (conteggi.size === 0) throw new Error('Scoperta degli aspetti fallita: nessuna risposta valida dal modello');

const temi = [...conteggi.values()].sort((a, b) => b.recensioni - a.recensioni || a.label.localeCompare(b.label));
// al modello vanno i 400 temi piu' frequenti (gli altri sono citati una sola volta)
const perModello = temi.slice(0, 400).map((t) => `${t.label} | ${t.recensioni} | +${t.positive} -${t.negative} =${t.neutral}`);

const SYSTEM = `You design the list of aspects for a system that analyses reviews for ${ctx.lettori_dei_risultati}.
${ctx.frase}
You receive free-text topic labels extracted from a sample of ${recensioniLette} reviews. Each line is: label | number of reviews that judged it | +positive -negative =neutral.
Merge synonyms and closely related labels into a final list of between 10 and 20 aspects.
Each aspect must be:
- a specific theme the authors judge, that the readers of the results can act on (not "overall experience", not the reviewed business itself);
- clearly distinct from the other aspects, with no overlaps;
- frequent enough: rare labels go into the closest aspect; a theme that is rare but serious for management (for example cleanliness or safety) may stay separate.
Frequent labels (judged by at least ${Math.max(3, Math.ceil(0.02 * recensioniLette))} reviews) must each appear in the includes of exactly one aspect. A frequent label that is a distinct part of the stay, run by different people or facilities, should not be hidden inside a broader aspect.
Put generic labels about the same area in the same aspect as the specific ones (for example generic staff labels together with specific staff roles only if you do not create separate aspects for those roles).
For each aspect give:
- aspect: short English identifier in snake_case (for example "breakfast", "room_comfort");
- name_it: short name in ${ctx.lingua_del_digest} for the readers of the results;
- description_it: one sentence in ${ctx.lingua_del_digest} saying exactly what the aspect covers and what it does not cover;
- includes: the source labels merged into it, copied exactly from the input.
Do not invent themes that are not supported by the labels.`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['aspects'],
  properties: {
    aspects: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['aspect', 'name_it', 'description_it', 'includes'],
        properties: {
          aspect: { type: 'string' },
          name_it: { type: 'string' },
          description_it: { type: 'string' },
          includes: { type: 'array', items: { type: 'string' } },
        },
      },
    },
  },
};

return [{
  json: {
    temi,
    recensioni_lette: recensioniLette,
    risposte_non_valide: risposteNonValide,
    body: {
      model: cfg.model,
      temperature: 0,
      seed: cfg.seed,
      max_tokens: 16000,
      response_format: { type: 'json_schema', json_schema: { name: 'aspects', strict: true, schema: SCHEMA } },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: perModello.join('\n') },
      ],
    },
  },
}];

// VALIDA L'ELENCO DEGLI ASPETTI E PREPARA LE ISTRUZIONI PER L'ANALISI
// Due origini possibili:
// - ELENCO FISSO (data/aspetti/aspetti_fissi.json): elenco con versione,
//   uguale da un giro all'altro, cosi' i numeri di periodi e giri diversi si
//   confrontano. E' il funzionamento normale in produzione.
// - SCOPERTA: se l'elenco fisso non c'e' (o si chiede di riscoprirlo), gli
//   aspetti emergono dal campione come descritto qui sotto.
// Controlla l'elenco proposto dal modello (identificativi unici e in
// snake_case, numero ragionevole di aspetti), misura quanta parte dei temi
// liberi e' coperta e scrive le istruzioni usate per analizzare OGNI
// recensione. Lo schema di risposta elenca gli aspetti ammessi: il modello
// non puo' inventarne di nuovi, quindi i nomi restano coerenti tra recensioni.
//
// Controllo di copertura: ogni tema FREQUENTE del campione (citato da almeno
// il 2% delle recensioni lette, minimo 3) deve finire in un aspetto. Se ne
// resta fuori qualcuno, il modello riceve l'elenco e ripropone la lista
// completa (fino a 2 volte).
const helpers = this.helpers;
const usoToken = []; // token delle chiamate fatte da questo nodo
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;
const ingresso = $input.first().json ?? {};
const elencoFisso = Array.isArray(ingresso.data?.aspetti) && !ingresso.choices ? ingresso.data : null;
let raccolta = null;
try {
  raccolta = $('Raccogli temi').first().json;
} catch (e) {
  raccolta = null; // scoperta non eseguita: si usa l'elenco fisso
}

function leggi(content) {
  const proposta = JSON.parse(content);
  const visti = new Set();
  const lista = [];
  for (const a of proposta.aspects ?? []) {
    const id = String(a.aspect ?? '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');
    if (!id || visti.has(id)) continue;
    visti.add(id);
    lista.push({
      aspect: id,
      nome: String(a.name_it ?? '').trim() || id,
      descrizione: String(a.description_it ?? '').trim(),
      temi_raggruppati: [...new Set((a.includes ?? []).map((s) => String(s).toLowerCase().trim()).filter(Boolean))],
    });
  }
  return lista;
}

async function dallaScoperta() {
const soglia = Math.max(3, Math.ceil(0.02 * raccolta.recensioni_lette));
const frequenti = raccolta.temi.filter((t) => t.recensioni >= soglia).map((t) => t.label);
const fuori = (lista) => {
  const dentro = new Set(lista.flatMap((a) => a.temi_raggruppati));
  return frequenti.filter((l) => !dentro.has(l));
};
// un tema in due aspetti rende ambigua la classificazione (es. "club lounge" sia nel
// servizio sia nel cibo): ogni tema deve stare in un solo aspetto
const doppi = (lista) => {
  const conta = new Map();
  for (const a of lista) for (const t of a.temi_raggruppati) conta.set(t, (conta.get(t) ?? 0) + 1);
  return [...conta].filter(([, n]) => n > 1).map(([t]) => t);
};
const daSistemare = (lista) => fuori(lista).length > 0 || doppi(lista).length > 0;

// lettura sicura: null se la risposta manca, e' tagliata o non e' JSON valido
const prova = (testo) => {
  try {
    const lista = leggi(testo);
    return lista.length >= 6 ? lista : null;
  } catch (e) {
    return null;
  }
};
const stato = (lista) => (lista ? { aspetti: lista.length, temi_frequenti_fuori: fuori(lista), temi_in_piu_aspetti: doppi(lista) } : { leggibile: false });

const primo = $input.first().json ?? {};
let content = primo.choices?.[0]?.message?.content ?? '';
let aspetti = prova(content);
const giri = [{
  giro: 1,
  fine_risposta: primo.choices?.[0]?.finish_reason ?? null,
  errore: primo.error ? JSON.stringify(primo.error).slice(0, 300) : undefined,
  ...stato(aspetti),
}];
let messaggi = [...raccolta.body.messages];
if (aspetti) messaggi.push({ role: 'assistant', content });

// fino a 3 giri in piu': si richiede l'elenco se illeggibile, altrimenti si chiede di correggerlo
for (let giro = 2; giro <= 4 && (!aspetti || daSistemare(aspetti)); giro++) {
  const conCorrezione = !!aspetti;
  let richiesta = messaggi;
  if (conCorrezione) {
    const richieste = [];
    if (fuori(aspetti).length) {
      richieste.push(`These frequent labels are not in the includes of any aspect: ${fuori(aspetti).join(', ')}. Put each of them in the right aspect, or create a new aspect if it is a distinct theme that management can act on.`);
    }
    if (doppi(aspetti).length) {
      richieste.push(`These labels are in the includes of more than one aspect: ${doppi(aspetti).join(', ')}. Each label must be in exactly one aspect. If a group of labels describes a distinct part of the stay (for example a specific facility), make it its own aspect instead of splitting it.`);
    }
    richiesta = [...messaggi, {
      role: 'user',
      content: `${richieste.join('\n')}\nReturn the complete list again. Keep between 10 and 20 aspects, aspects must not overlap, and keep all the other rules.`,
    }];
  }
  try {
    const res = await helpers.httpRequest({
      method: 'POST',
      url: cfg.base_url + '/chat/completions',
      headers: { Authorization: 'Bearer ' + $env.OPENAI_API_KEY },
      body: { ...raccolta.body, messages: richiesta },
      json: true,
      timeout: 240000,
    });
    if (res.usage) usoToken.push(res.usage);
    const nuovo = res.choices?.[0]?.message?.content ?? '';
    const lista = prova(nuovo);
    giri.push({ giro, tipo: conCorrezione ? 'correzione' : 'nuova_richiesta', fine_risposta: res.choices?.[0]?.finish_reason ?? null, ...stato(lista) });
    if (lista) {
      // si tiene la nuova proposta e la conversazione prosegue da li'
      messaggi = [...richiesta, { role: 'assistant', content: nuovo }];
      content = nuovo;
      aspetti = lista;
    }
  } catch (e) {
    giri.push({ giro, errore: e.message });
  }
}
if (!aspetti) {
  throw new Error('Il modello non ha restituito un elenco di aspetti leggibile dopo 4 tentativi: ' + JSON.stringify(giri));
}
if (aspetti.length > 24) {
  throw new Error(`Elenco di aspetti non plausibile: ${aspetti.length} aspetti`);
}
// se dopo i giri un tema e' ancora in piu' aspetti, resta solo nel primo (regola fissa, registrata)
const temiTolti = [];
{
  const giaUsati = new Set();
  for (const a of aspetti) {
    a.temi_raggruppati = a.temi_raggruppati.filter((t) => {
      if (giaUsati.has(t)) {
        temiTolti.push({ tema: t, tolto_da: a.aspect });
        return false;
      }
      giaUsati.add(t);
      return true;
    });
  }
}
  return { aspetti, giri, temiTolti, soglia };
}

let aspetti, giri, temiTolti, soglia, origine, versione;
if (elencoFisso) {
  // elenco fisso: controlli minimi e nessuna chiamata al modello
  const visti = new Set();
  aspetti = elencoFisso.aspetti.map((a) => ({
    aspect: String(a.aspect ?? '').trim(),
    nome: String(a.nome ?? a.aspect ?? '').trim(),
    descrizione: String(a.descrizione ?? '').trim(),
    temi_raggruppati: (a.temi_raggruppati ?? []).map((t) => String(t).toLowerCase().trim()).filter(Boolean),
  }));
  for (const a of aspetti) {
    if (!/^[a-z][a-z0-9_]*$/.test(a.aspect) || visti.has(a.aspect)) throw new Error(`Elenco fisso non valido: identificativo "${a.aspect}"`);
    visti.add(a.aspect);
  }
  if (aspetti.length < 3) throw new Error('Elenco fisso con meno di 3 aspetti');
  versione = String(elencoFisso.versione ?? 'senza versione');
  origine = 'elenco fisso';
  giri = [{ origine, versione }];
  temiTolti = [];
  soglia = null;
} else {
  ({ aspetti, giri, temiTolti, soglia } = await dallaScoperta());
  origine = 'scoperta dalle recensioni';
  versione = 'scoperta del ' + new Date().toISOString().slice(0, 10);
}

// copertura (solo con la scoperta): quota delle citazioni di temi liberi che finiscono in un aspetto
const inclusi = new Set(aspetti.flatMap((a) => a.temi_raggruppati));
const totale = raccolta && !elencoFisso ? raccolta.temi.reduce((s, t) => s + t.recensioni, 0) : 0;
const coperte = totale ? raccolta.temi.filter((t) => inclusi.has(t.label)).reduce((s, t) => s + t.recensioni, 0) : 0;
const nonCoperti = totale ? raccolta.temi.filter((t) => !inclusi.has(t.label)).slice(0, 50) : [];

// categorie di segnalazione: dal file di contesto
const CATEGORIE = Object.fromEntries(Object.entries(ctx.categorie).map(([k, v]) => [k, v.definizione]));

// ogni aspetto con TUTTI i temi che raggruppa (fino a 25): cosi' il modello sa,
// per esempio, che "concierge" sta gia' dentro l'aspetto del personale
const elenco = aspetti.map((a) => `- ${a.aspect}: ${a.descrizione} Includes: ${a.temi_raggruppati.slice(0, 25).join(', ')}.`).join('\n');
const elencoCategorie = Object.entries(CATEGORIE).map(([k, v]) => `- ${k}: ${v}`).join('\n');

const SYSTEM = `You analyse reviews for ${ctx.lettori_dei_risultati}. Reviews can be in any language, of any length, and may contain noise.
${ctx.frase}
The input is a list of independent reviews. Analyse each review ONLY on its own text: never use content of one review in the result of another.
For EACH review in the input return one result with:
- review_id: copied exactly.
- language: ISO 639-1 code of the language of the review text (for example en, es, ja).
- overall_sentiment: the author's overall evaluation as expressed in the text.
  positive = clearly satisfied, criticisms are minor or absent;
  negative = clearly dissatisfied, praise is minor or absent;
  mixed = both substantial praise and substantial criticism;
  neutral = no clear evaluation (descriptive or factual text).
  Judge the text. The rating (from ${ctx.voto.minimo} to ${ctx.voto.massimo}) is given only as context.
- aspects: one entry for each aspect in the list below on which the author expresses a judgement. Use only the aspect identifiers from the list. Do not add an aspect that is only mentioned without a judgement.
  sentiment: positive, negative, or neutral (the judgement is lukewarm or explicitly balanced, for example "breakfast was ok").
  If the same aspect gets both praise and criticism, choose the prevailing judgement; if they really balance, use neutral.
- unmapped: short English labels (1-3 words) of judged topics that fit none of the aspects, considering their descriptions and the topics they include. A topic that belongs to an aspect goes in aspects, not here. Empty list if none.
- attention: issues that ${ctx.lettori_dei_risultati} should look at, ONLY if the review explicitly describes them. For each issue:
  category: one of the codes below;
  summary_it: what happened, in Italian, maximum 20 words, factual, no speculation;
  evidence: a short excerpt copied verbatim from the review (maximum 25 words, original language, no changes).
  Ordinary mild criticisms (for example: ${ctx.critiche_ordinarie_da_non_segnalare}) are NOT attention issues.
  Report only issues caused by, or under the responsibility of, ${ctx.oggetto_recensito} (its staff, services, premises or product). Problems with third parties or the surroundings are NOT attention issues. Empty list if none.

Aspects:
${elenco}

Attention categories:
${elencoCategorie}

Never add information that is not in the review.`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['review_id', 'language', 'overall_sentiment', 'aspects', 'unmapped', 'attention'],
        properties: {
          review_id: { type: 'string' },
          language: { type: 'string' },
          overall_sentiment: { type: 'string', enum: ['positive', 'negative', 'mixed', 'neutral'] },
          aspects: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['aspect', 'sentiment'],
              properties: {
                aspect: { type: 'string', enum: aspetti.map((a) => a.aspect) },
                sentiment: { type: 'string', enum: ['positive', 'negative', 'neutral'] },
              },
            },
          },
          unmapped: { type: 'array', items: { type: 'string' } },
          attention: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['category', 'summary_it', 'evidence'],
              properties: {
                category: { type: 'string', enum: Object.keys(CATEGORIE) },
                summary_it: { type: 'string' },
                evidence: { type: 'string' },
              },
            },
          },
        },
      },
    },
  },
};

return [{
  json: {
    aspetti,
    origine_aspetti: origine,
    uso_token: usoToken,
    versione_aspetti: versione,
    linea_di_base: elencoFisso?.linea_di_base_temi_fuori_elenco ?? null,
    categorie_attenzione: Object.keys(CATEGORIE),
    copertura_temi_pct: totale ? Math.round((1000 * coperte) / totale) / 10 : null,
    soglia_temi_frequenti: soglia,
    giri_consolidamento: giri,
    temi_tolti_perche_doppi: temiTolti,
    temi_non_coperti: nonCoperti,
    system_prompt: SYSTEM,
    // modello della richiesta: i nodi successivi aggiungono solo i messaggi
    body_base: {
      model: cfg.model,
      temperature: 0,
      seed: cfg.seed,
      max_tokens: 6000,
      response_format: { type: 'json_schema', json_schema: { name: 'review_analysis', strict: true, schema: SCHEMA } },
    },
  },
}];

// PREPARA LE RICHIESTE DI ANALISI
// Le recensioni (tranne le vuote e i duplicati esatti, gestiti a parte) vengono mandate al modello a gruppi:
// al massimo BATCH_SIZE recensioni e circa 12.000 caratteri per richiesta, cosi' anche le recensioni lunghe
// restano intere e le risposte non vengono troncate.
//
// MEMORIA DELLE ANALISI (16/11): si mandano al modello solo le recensioni NUOVE o CAMBIATE. Per ogni recensione
// gia' analizzata la memoria (memoria_analisi.json nella cartella dei risultati) tiene la risposta del modello e
// una «firma»: l'impronta di istruzioni, elenco degli aspetti e categorie (tutto nel system prompt), modello e
// impostazioni della richiesta, dimensione dei gruppi e testo della recensione. Se cambia una sola di queste cose
// la firma cambia e la recensione si rianalizza: un nuovo elenco degli aspetti o un nuovo contesto fanno
// rianalizzare TUTTO da soli. La stessa firma la calcola il nodo «Valida e completa».
const crypto = require('crypto');
const cfg = $('Configurazione').first().json;
const tax = $('Valida tassonomia').first().json;
const recensioni = $('Recensioni pronte')
  .all()
  .map((i) => i.json)
  .filter((r) => !r.vuota && !r.duplicato_di);

// stesso formato usato nei ritentativi (nodo "Valida e completa")
const payload = (r) => ({ review_id: r.review_id, rating: r.rating, title: r.title, text: r.text || r.title });
const firma = (r) => crypto.createHash('sha1').update(JSON.stringify([tax.system_prompt, tax.body_base, cfg.batch_size, payload(r)]), 'utf8').digest('hex');
let memoria = {};
try {
  memoria = $('Estrai memoria analisi').first().json.data?.voci ?? {};
} catch (e) {
  memoria = {}; // primo giro: nessuna memoria
}
const daMandare = recensioni.filter((r) => memoria[r.review_id]?.firma !== firma(r));

const MAX_CARATTERI = 12000;
const gruppi = [];
let corrente = [];
let caratteri = 0;
for (const r of daMandare) {
  const lung = r.title.length + r.text.length;
  if (corrente.length && (corrente.length >= cfg.batch_size || caratteri + lung > MAX_CARATTERI)) {
    gruppi.push(corrente);
    corrente = [];
    caratteri = 0;
  }
  corrente.push(r);
  caratteri += lung;
}
if (corrente.length) gruppi.push(corrente);

// niente di nuovo da analizzare: un solo elemento segnaposto, che salta la chiamata al modello
// (nodo «Richieste da fare?») e arriva direttamente a «Valida e completa»
if (!gruppi.length) return [{ json: { nessuna_richiesta: true, dalla_memoria: recensioni.length } }];

return gruppi.map((g) => ({
  json: {
    ids: g.map((r) => r.review_id),
    body: {
      ...tax.body_base,
      messages: [
        { role: 'system', content: tax.system_prompt },
        { role: 'user', content: JSON.stringify(g.map(payload)) },
      ],
    },
  },
}));

// VALIDA E COMPLETA L'ANALISI DI OGNI RECENSIONE
// 1. legge le risposte del modello e le abbina alle recensioni per review_id;
// 2. le recensioni mancanti o con risposta non valida vengono richieste di nuovo
//    una per una (fino a 3 tentativi);
// 3. normalizza i valori (solo i sentiment e gli aspetti ammessi);
// 4. tiene una segnalazione solo se la frase citata come prova si ritrova
//    davvero nel testo della recensione (niente informazioni inventate);
// 5. applica le regole per needs_attention e scrive il motivo.
const helpers = this.helpers;
const usoToken = []; // token dei ritentativi
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;
const tax = $('Valida tassonomia').first().json;
const recensioni = $('Recensioni pronte').all().map((i) => i.json);
const perId = new Map(recensioni.map((r) => [r.review_id, r]));
const idAspetti = new Set(tax.aspetti.map((a) => a.aspect));

const OVERALL = ['positive', 'negative', 'mixed', 'neutral'];
const SENT = ['positive', 'negative', 'neutral'];
// categorie di segnalazione con nome e priorita': dal file di contesto
const CATEGORIE = ctx.categorie;
const ORDINE_PRIORITA = { alta: 0, media: 1, bassa: 2 };

const payload = (r) => ({ review_id: r.review_id, rating: r.rating, title: r.title, text: r.text || r.title });

const valido = (g) =>
  g &&
  typeof g.review_id === 'string' &&
  OVERALL.includes(g.overall_sentiment) &&
  Array.isArray(g.aspects) &&
  Array.isArray(g.attention);

// --- 0. memoria delle analisi: le recensioni con la stessa firma del giro prima riprendono la risposta salvata
// (stessa firma del nodo «Prepara richieste analisi»: istruzioni, elenco, categorie, modello, gruppi, testo)
const crypto = require('crypto');
const firma = (r) => crypto.createHash('sha1').update(JSON.stringify([tax.system_prompt, tax.body_base, cfg.batch_size, payload(r)]), 'utf8').digest('hex');
let memoria = {};
try {
  memoria = $('Estrai memoria analisi').first().json.data?.voci ?? {};
} catch (e) {
  memoria = {};
}
const grezzi = new Map();
const ritentataNellaMemoria = new Set();
const firme = new Map();
for (const r of recensioni) {
  if (r.vuota || r.duplicato_di) continue;
  const f = firma(r);
  firme.set(r.review_id, f);
  const m = memoria[r.review_id];
  if (m && m.firma === f && valido(m.risposta)) {
    grezzi.set(r.review_id, m.risposta);
    if (m.ritentata) ritentataNellaMemoria.add(r.review_id);
  }
}
const dallaMemoria = grezzi.size;

// --- 1. risposte del primo giro (solo le recensioni nuove o cambiate)
let risposteNonValide = 0;
const richieste = $input.all().filter((it) => !it.json?.nessuna_richiesta);
for (const it of richieste) {
  const content = it.json?.choices?.[0]?.message?.content;
  let dati = null;
  try {
    dati = JSON.parse(content);
  } catch (e) {
    risposteNonValide++;
    continue;
  }
  for (const g of dati.results ?? []) {
    if (perId.has(g.review_id) && !grezzi.has(g.review_id) && valido(g)) grezzi.set(g.review_id, g);
  }
}

// --- 2. ritentativi una recensione alla volta
const attesa = (ms) => new Promise((ok) => setTimeout(ok, ms));
async function chiediUna(r) {
  const body = {
    ...tax.body_base,
    messages: [
      { role: 'system', content: tax.system_prompt },
      { role: 'user', content: JSON.stringify([payload(r)]) },
    ],
  };
  let errore = null;
  for (let tentativo = 1; tentativo <= 3; tentativo++) {
    try {
      const res = await helpers.httpRequest({
        method: 'POST',
        url: cfg.base_url + '/chat/completions',
        headers: { Authorization: 'Bearer ' + $env.OPENAI_API_KEY },
        body,
        json: true,
        timeout: 180000,
      });
      if (res.usage) usoToken.push(res.usage);
      const g = (JSON.parse(res.choices[0].message.content).results ?? []).find((x) => x.review_id === r.review_id);
      if (valido(g)) return { g, errore: null };
      errore = 'risposta senza la recensione richiesta';
    } catch (e) {
      errore = e.message;
    }
    await attesa(2000 * tentativo);
  }
  return { g: null, errore };
}

const daAnalizzare = recensioni.filter((r) => !r.vuota && !r.duplicato_di);
const mancanti = daAnalizzare.filter((r) => !grezzi.has(r.review_id));
const ritentate = new Set();
const fallite = [];
for (const r of mancanti) {
  const { g, errore } = await chiediUna(r);
  if (g) {
    grezzi.set(r.review_id, g);
    ritentate.add(r.review_id);
  } else fallite.push({ review_id: r.review_id, errore });
}

// --- 3/4. normalizzazione e controllo delle prove
const norm = (s) =>
  String(s ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[“”„«»"]/g, '"')
    .replace(/[‘’`´]/g, "'")
    .replace(/…/g, '...')
    .replace(/\s+/g, ' ')
    .trim();

function provaNelTesto(evidenza, testo) {
  const e = norm(evidenza).replace(/^["'.\s]+|["'.\s]+$/g, '');
  if (e.length < 3) return false;
  const t = norm(testo);
  if (t.includes(e)) return true;
  // citazione con omissioni "...": ogni pezzo deve esserci
  const pezzi = e.split(/\.{3,}/).map((p) => p.trim()).filter((p) => p.length >= 3);
  if (pezzi.length > 1 && pezzi.every((p) => t.includes(p))) return true;
  // quasi letterale: almeno il 90% delle parole della citazione compare nel testo
  const parole = e.match(/[\p{L}\p{N}]+/gu) ?? [];
  if (parole.length < 4) return false;
  return parole.filter((p) => t.includes(p)).length / parole.length >= 0.9;
}

const scarti = { aspetti_non_ammessi: 0, segnalazioni_senza_prova: [] };

const normTema = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9 &/-]/g, ' ').replace(/\s+/g, ' ').trim();
const temiInclusi = new Set(tax.aspetti.flatMap((a) => a.temi_raggruppati.map(normTema)));
// coperto se il tema (anche al singolare/plurale) e' uno dei temi raggruppati negli aspetti
const giaCoperto = (u) => temiInclusi.has(u) || temiInclusi.has(u.replace(/s$/, '')) || temiInclusi.has(u + 's');

function costruisci(r, g, stato) {
  let language = String(g.language ?? '').toLowerCase().trim();
  if (!/^[a-z]{2,3}(-[a-z0-9]{2,4})?$/.test(language)) language = 'und';

  const aspetti = new Map();
  for (const a of g.aspects ?? []) {
    if (!idAspetti.has(a.aspect) || !SENT.includes(a.sentiment)) {
      scarti.aspetti_non_ammessi++;
      continue;
    }
    if (!aspetti.has(a.aspect)) aspetti.set(a.aspect, a.sentiment);
    else if (aspetti.get(a.aspect) !== a.sentiment) aspetti.set(a.aspect, 'neutral'); // giudizi opposti sullo stesso aspetto
  }

  const testo = r.title + '\n' + r.text;
  const segnalazioni = [];
  for (const s of g.attention ?? []) {
    if (!CATEGORIE[s.category]) continue;
    if (!provaNelTesto(s.evidence, testo)) {
      // la prova non e' nel testo: e' inventata o presa da un'altra recensione dello stesso gruppo?
      const altra = recensioni.find((x) => x.review_id !== r.review_id && provaNelTesto(s.evidence, x.title + '\n' + x.text));
      scarti.segnalazioni_senza_prova.push({
        review_id: r.review_id,
        categoria: s.category,
        evidenza: s.evidence,
        tipo: altra ? 'presa_da_un_altra_recensione' : 'non_trovata_in_nessuna_recensione',
        recensione_di_origine: altra ? altra.review_id : null,
      });
      continue;
    }
    segnalazioni.push({
      categoria: s.category,
      nome_categoria: CATEGORIE[s.category].nome,
      priorita: CATEGORIE[s.category].priorita,
      sintesi: String(s.summary_it ?? '').trim().replace(/\s+/g, ' ').slice(0, 200),
      evidenza: String(s.evidence ?? '').trim(),
    });
  }

  // --- 5. regole per needs_attention
  const motivi = [];
  const viste = new Set();
  for (const s of segnalazioni) {
    if (viste.has(s.categoria)) continue;
    viste.add(s.categoria);
    motivi.push(`${s.nome_categoria}: ${s.sintesi}`);
  }
  let priorita = segnalazioni.length
    ? segnalazioni.map((s) => s.priorita).sort((a, b) => ORDINE_PRIORITA[a] - ORDINE_PRIORITA[b])[0]
    : null;
  const V = ctx.voto;
  if (r.rating !== null && r.rating <= V.basso_fino_a) {
    motivi.push(`voto molto basso (${r.rating} su ${V.massimo})`);
    priorita ??= 'bassa';
  }
  if (r.rating !== null && r.rating >= V.alto_da && g.overall_sentiment === 'negative') {
    motivi.push(`voto alto (${r.rating} su ${V.massimo}) ma testo negativo: da verificare`);
    priorita ??= 'bassa';
  }
  if (r.rating !== null && r.rating <= V.basso_fino_a && g.overall_sentiment === 'positive') {
    motivi.push(`voto basso (${r.rating} su ${V.massimo}) ma testo positivo: possibile errore di chi ha scritto`);
    priorita ??= 'bassa';
  }
  if (r.sospetta) {
    motivi.unshift(`possibile testo manipolatorio rilevato dal guardrail (${r.guardrail_scattati.join(', ')}): verificare, esclusa dai conteggi`);
    if (priorita !== 'alta') priorita = 'media';
  }

  return {
    review_id: r.review_id,
    stato,
    sospetta: r.sospetta,
    rating: r.rating,
    published_date: r.published_date,
    anno: r.anno,
    language,
    overall_sentiment: g.overall_sentiment,
    aspects: [...aspetti].map(([aspect, sentiment]) => ({ aspect, sentiment })),
    needs_attention: motivi.length > 0,
    attention_reason: motivi.length ? motivi.join('; ') : null,
    priorita: motivi.length ? priorita : null,
    segnalazioni,
    // temi fuori elenco: si tolgono quelli che stanno gia' dentro un aspetto (il modello a volte
    // li ripete qui), cosi' la misura conta solo i temi davvero non coperti
    unmapped: [...new Set((g.unmapped ?? []).map(normTema).filter(Boolean))].filter((u) => !giaCoperto(u)),
  };
}

const risultati = new Map();
for (const r of daAnalizzare) {
  const g = grezzi.get(r.review_id);
  if (g) risultati.set(r.review_id, costruisci(r, g, ritentate.has(r.review_id) || ritentataNellaMemoria.has(r.review_id) ? 'ritentata' : 'ok'));
  else {
    // analisi non riuscita dopo i ritentativi: nessun giudizio inventato,
    // la recensione viene segnalata perche' qualcuno la legga
    risultati.set(r.review_id, {
      review_id: r.review_id, stato: 'fallita', sospetta: r.sospetta, rating: r.rating, published_date: r.published_date, anno: r.anno,
      language: 'und', overall_sentiment: 'neutral', aspects: [], needs_attention: true,
      attention_reason: 'analisi automatica non riuscita: da leggere manualmente', priorita: 'bassa', segnalazioni: [], unmapped: [],
    });
  }
}
for (const r of recensioni) {
  if (r.vuota) {
    risultati.set(r.review_id, {
      review_id: r.review_id, stato: 'vuota', sospetta: r.sospetta, rating: r.rating, published_date: r.published_date, anno: r.anno,
      language: 'und', overall_sentiment: 'neutral', aspects: [], needs_attention: false,
      attention_reason: null, priorita: null, segnalazioni: [], unmapped: [],
    });
  } else if (r.duplicato_di) {
    // duplicato esatto: stessa analisi dell'originale, escluso dai conteggi
    const o = risultati.get(r.duplicato_di);
    risultati.set(r.review_id, { ...o, review_id: r.review_id, stato: 'duplicato' });
  }
}

// memoria aggiornata: una voce per ogni recensione con una risposta valida (le fallite si riprovano al giro dopo)
const voci = {};
for (const r of daAnalizzare) {
  const g = grezzi.get(r.review_id);
  if (g) voci[r.review_id] = { firma: firme.get(r.review_id), ritentata: ritentate.has(r.review_id) || ritentataNellaMemoria.has(r.review_id), risposta: g };
}

const out = recensioni.map((r) => risultati.get(r.review_id));
out[0] = {
  ...out[0],
  _memoria: { versione_formato: 1, aggiornata_il: new Date().toISOString(), voci },
  _analisi: {
    dalla_memoria: dallaMemoria,
    analizzate_in_questo_giro: daAnalizzare.length - dallaMemoria,
    richieste_primo_giro: richieste.length,
    uso_token_ritentativi: usoToken,
    risposte_non_valide: risposteNonValide,
    recensioni_ritentate: [...ritentate],
    recensioni_fallite: fallite,
    aspetti_non_ammessi_scartati: scarti.aspetti_non_ammessi,
    segnalazioni_scartate_senza_prova: scarti.segnalazioni_senza_prova,
  },
};
return out.map((r) => ({ json: r }));

// AGGREGAZIONE
// Dalle analisi delle singole recensioni calcola, per ogni aspetto, quanto e'
// apprezzato e quanto e' criticato, sull'intero archivio e nel tempo.
// Tutti i numeri del digest vengono da qui.
//
// Scelte:
// - Si contano le recensioni, non le frasi: un aspetto vale al massimo 1 per recensione.
// - Classifica principale per VOLUME: quante recensioni apprezzano/criticano
//   l'aspetto (cio' che tocca piu' ospiti). Classifica secondaria per TASSO:
//   tra le recensioni che ne parlano, quota di giudizi positivi/negativi,
//   solo per aspetti con almeno MIN_MENTIONS_RATE_RANKING menzioni.
// - Tempo: base annuale (data di pubblicazione, sempre presente). Gli anni con
//   poche recensioni vengono uniti ai successivi finche' il periodo ha almeno
//   MIN_REVIEWS_PER_PERIOD recensioni, perche' l'archivio non e' uniforme.
// - Andamento: l'ultimo periodo e' confrontato con tutti i precedenti e con il
//   periodo subito prima (test su due proporzioni). Un cambiamento e'
//   "significativo" solo se resta tale dopo la correzione per confronti
//   multipli (Benjamini-Hochberg, falsi positivi attesi al massimo 10%).
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;
const tax = $('Valida tassonomia').first().json;
const fileInfo = $('Recensioni pronte').first().json._file;
const tutte = $input.all().map((i) => i.json);
const infoAnalisi = tutte[0]._analisi;

// nei conteggi: solo recensioni analizzate, non duplicate e non sospette di manipolazione
const valide = tutte.filter((r) => (r.stato === 'ok' || r.stato === 'ritentata') && !r.sospetta);
const N = valide.length;
if (N === 0) throw new Error('Nessuna recensione analizzata correttamente: aggregazione impossibile');

const pct = (a, b) => (b ? Math.round((1000 * a) / b) / 10 : null);
const media = (xs) => (xs.length ? Math.round((100 * xs.reduce((s, x) => s + x, 0)) / xs.length) / 100 : null);

function wilson(k, n) {
  if (!n) return null;
  const z = 1.96, p = k / n, d = 1 + (z * z) / n;
  const c = (p + (z * z) / (2 * n)) / d;
  const m = (z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n))) / d;
  return [Math.round(1000 * Math.max(0, c - m)) / 10, Math.round(1000 * Math.min(1, c + m)) / 10];
}
// funzione di ripartizione normale (approssimazione di Abramowitz-Stegun)
function phi(x) {
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const d = 0.3989423 * Math.exp((-x * x) / 2);
  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
  return x > 0 ? 1 - p : p;
}
function dueProporzioni(k1, n1, k0, n0) {
  const p1 = k1 / n1, p0 = k0 / n0, p = (k1 + k0) / (n1 + n0);
  const se = Math.sqrt(p * (1 - p) * (1 / n1 + 1 / n0));
  const z = se > 0 ? (p1 - p0) / se : 0;
  return { z: Math.round(100 * z) / 100, p_value: 2 * (1 - phi(Math.abs(z))) };
}

function contaSentiment(lista) {
  const c = { positive: 0, negative: 0, mixed: 0, neutral: 0 };
  for (const r of lista) c[r.overall_sentiment]++;
  return Object.fromEntries(Object.entries(c).map(([k, v]) => [k, { recensioni: v, pct: pct(v, lista.length) }]));
}

function statAspetti(lista) {
  const n = lista.length;
  const out = {};
  for (const a of tax.aspetti) {
    let pos = 0, neg = 0, neu = 0;
    for (const r of lista) {
      const x = r.aspects.find((y) => y.aspect === a.aspect);
      if (!x) continue;
      if (x.sentiment === 'positive') pos++;
      else if (x.sentiment === 'negative') neg++;
      else neu++;
    }
    const m = pos + neg + neu;
    out[a.aspect] = {
      aspect: a.aspect,
      nome: a.nome,
      menzioni: m,
      positive: pos,
      negative: neg,
      neutral: neu,
      pct_recensioni_che_ne_parlano: pct(m, n),
      pct_recensioni_che_lo_apprezzano: pct(pos, n),
      pct_recensioni_che_lo_criticano: pct(neg, n),
      pct_positive_su_menzioni: pct(pos, m),
      pct_negative_su_menzioni: pct(neg, m),
      ic95_pct_negative_su_menzioni: wilson(neg, m),
      saldo: m ? Math.round((100 * (pos - neg)) / m) / 100 : null,
    };
  }
  return out;
}

const classifica = (stat, campo, filtro = () => true) =>
  Object.values(stat)
    .filter((s) => s[campo] > 0 && filtro(s))
    .sort((a, b) => b[campo] - a[campo] || b.menzioni - a.menzioni || a.aspect.localeCompare(b.aspect));

// --- intero archivio
const statTotali = statAspetti(valide);
const conPos = (s) => ({ aspect: s.aspect, nome: s.nome, recensioni_positive: s.positive, pct_recensioni_che_lo_apprezzano: s.pct_recensioni_che_lo_apprezzano, pct_positive_su_menzioni: s.pct_positive_su_menzioni, menzioni: s.menzioni });
const conNeg = (s) => ({ aspect: s.aspect, nome: s.nome, recensioni_negative: s.negative, pct_recensioni_che_lo_criticano: s.pct_recensioni_che_lo_criticano, pct_negative_su_menzioni: s.pct_negative_su_menzioni, menzioni: s.menzioni });
const numera = (lista) => lista.map((x, i) => ({ posizione: i + 1, ...x }));
const minM = cfg.min_mentions_rate_ranking;

const classifiche = {
  piu_apprezzati: numera(classifica(statTotali, 'positive').map(conPos)),
  piu_criticati: numera(classifica(statTotali, 'negative').map(conNeg)),
  piu_apprezzati_per_tasso: numera(classifica(statTotali, 'pct_positive_su_menzioni', (s) => s.menzioni >= minM).map(conPos)),
  piu_criticati_per_tasso: numera(classifica(statTotali, 'pct_negative_su_menzioni', (s) => s.menzioni >= minM).map(conNeg)),
};

// --- periodi
const perAnno = new Map();
for (const r of valide) if (r.anno) perAnno.set(r.anno, (perAnno.get(r.anno) ?? 0) + 1);
const anni = [...perAnno.keys()].sort((a, b) => a - b);
const periodiGrezzi = [];
let corrente = null;
for (const a of anni) {
  corrente ??= { dal: a, al: a, n: 0 };
  corrente.al = a;
  corrente.n += perAnno.get(a);
  if (corrente.n >= cfg.min_reviews_per_period) {
    periodiGrezzi.push(corrente);
    corrente = null;
  }
}
if (corrente) {
  // gli ultimi anni rimasti sotto la soglia si uniscono al periodo precedente
  if (periodiGrezzi.length) {
    const u = periodiGrezzi[periodiGrezzi.length - 1];
    u.al = corrente.al;
    u.n += corrente.n;
  } else periodiGrezzi.push(corrente);
}

const periodi = periodiGrezzi.map((p) => {
  const lista = valide.filter((r) => r.anno >= p.dal && r.anno <= p.al);
  const stat = statAspetti(lista);
  return {
    periodo: p.dal === p.al ? String(p.dal) : `${p.dal}-${p.al}`,
    dal_anno: p.dal,
    al_anno: p.al,
    recensioni: lista.length,
    voto_medio: media(lista.filter((r) => r.rating !== null).map((r) => r.rating)),
    sentiment_complessivo: contaSentiment(lista),
    piu_apprezzati: classifica(stat, 'positive').slice(0, 5).map((s) => s.aspect),
    piu_criticati: classifica(stat, 'negative').slice(0, 5).map((s) => s.aspect),
    aspetti: stat,
  };
});

// --- andamento: ultimo periodo contro i precedenti
const andamento = [];
if (periodi.length >= 2) {
  const ultimo = periodi[periodi.length - 1];
  const penultimo = periodi[periodi.length - 2];
  const listaUltimo = valide.filter((r) => r.anno >= ultimo.dal_anno && r.anno <= ultimo.al_anno);
  const listaPrima = valide.filter((r) => r.anno && r.anno < ultimo.dal_anno);
  const listaPenultimo = valide.filter((r) => r.anno >= penultimo.dal_anno && r.anno <= penultimo.al_anno);
  const confronti = [
    { contro: 'tutti_i_periodi_precedenti', etichetta: listaPrima.length ? `${periodi[0].dal_anno}-${penultimo.al_anno}` : null, lista: listaPrima },
    { contro: 'periodo_precedente', etichetta: penultimo.periodo, lista: listaPenultimo },
  ];
  const conta = (lista, aspect, sentiment) => lista.filter((r) => r.aspects.some((x) => x.aspect === aspect && x.sentiment === sentiment)).length;
  for (const c of confronti) {
    if (c.lista.length < 30 || listaUltimo.length < 30) continue;
    for (const a of tax.aspetti) {
      for (const [misura, sentiment] of [['pct_recensioni_che_lo_criticano', 'negative'], ['pct_recensioni_che_lo_apprezzano', 'positive']]) {
        const k1 = conta(listaUltimo, a.aspect, sentiment);
        const k0 = conta(c.lista, a.aspect, sentiment);
        if (k1 + k0 < 10) continue; // troppo pochi casi per dire qualcosa
        const t = dueProporzioni(k1, listaUltimo.length, k0, c.lista.length);
        andamento.push({
          aspect: a.aspect,
          nome: a.nome,
          misura,
          ultimo_periodo: ultimo.periodo,
          confronto_con: c.contro,
          periodo_di_confronto: c.etichetta,
          valore_ultimo_periodo: pct(k1, listaUltimo.length),
          valore_periodo_di_confronto: pct(k0, c.lista.length),
          differenza_punti: Math.round(10 * (pct(k1, listaUltimo.length) - pct(k0, c.lista.length))) / 10,
          z: t.z,
          p_value: Math.round(10000 * t.p_value) / 10000,
        });
      }
    }
  }
  // Benjamini-Hochberg sul complesso dei confronti
  const ordinati = [...andamento].sort((a, b) => a.p_value - b.p_value);
  const m = ordinati.length;
  let soglia = -1;
  ordinati.forEach((x, i) => {
    if (x.p_value <= ((i + 1) / m) * 0.1) soglia = i;
  });
  ordinati.forEach((x, i) => {
    x.significativo = i <= soglia;
    x.direzione = x.differenza_punti > 0 ? 'aumento' : x.differenza_punti < 0 ? 'calo' : 'stabile';
  });
}

// --- per lingua
// La lingua e' un'informazione: se le recensioni negative venissero soprattutto da
// una lingua, sarebbe un segnale per la direzione. Ogni lingua con almeno
// MIN_LINGUA recensioni e' confrontata con tutte le altre insieme sulla quota di
// recensioni negative o miste (test su due proporzioni, correzione Benjamini-Hochberg).
const MIN_LINGUA = 15;
const negativeOMiste = (lista) => lista.filter((r) => r.overall_sentiment === 'negative' || r.overall_sentiment === 'mixed').length;
const conteggioLingue = new Map();
for (const r of valide) conteggioLingue.set(r.language, (conteggioLingue.get(r.language) ?? 0) + 1);
const perLingua = [...conteggioLingue].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([lingua, n]) => {
  const lista = valide.filter((r) => r.language === lingua);
  const altre = valide.filter((r) => r.language !== lingua);
  const base = {
    lingua,
    recensioni: n,
    voto_medio: media(lista.filter((r) => r.rating !== null).map((r) => r.rating)),
    sentiment_complessivo: contaSentiment(lista),
  };
  if (n < MIN_LINGUA || altre.length < 30) return { ...base, confronto_con_le_altre_lingue: null };
  const k1 = negativeOMiste(lista);
  const k0 = negativeOMiste(altre);
  const t = dueProporzioni(k1, n, k0, altre.length);
  return {
    ...base,
    confronto_con_le_altre_lingue: {
      misura: 'pct_recensioni_negative_o_miste',
      valore_lingua: pct(k1, n),
      valore_altre_lingue: pct(k0, altre.length),
      differenza_punti: Math.round(10 * (pct(k1, n) - pct(k0, altre.length))) / 10,
      z: t.z,
      p_value: Math.round(10000 * t.p_value) / 10000,
    },
  };
});
{
  const confronti = perLingua.map((x) => x.confronto_con_le_altre_lingue).filter(Boolean).sort((a, b) => a.p_value - b.p_value);
  let soglia = -1;
  confronti.forEach((x, i) => {
    if (x.p_value <= ((i + 1) / confronti.length) * 0.1) soglia = i;
  });
  confronti.forEach((x, i) => {
    x.significativo = i <= soglia;
    x.direzione = x.differenza_punti > 0 ? 'piu_negative' : x.differenza_punti < 0 ? 'meno_negative' : 'uguale';
  });
}

// --- serie annuale grezza (conteggi), per chi vuole ricalcolare con altre granularita'
const serieAnnuale = anni.map((anno) => {
  const lista = valide.filter((r) => r.anno === anno);
  const aspetti = {};
  for (const a of tax.aspetti) {
    const c = { positive: 0, negative: 0, neutral: 0 };
    for (const r of lista) {
      const x = r.aspects.find((y) => y.aspect === a.aspect);
      if (x) c[x.sentiment]++;
    }
    aspetti[a.aspect] = c;
  }
  const s = { positive: 0, negative: 0, mixed: 0, neutral: 0 };
  for (const r of lista) s[r.overall_sentiment]++;
  return { anno, recensioni: lista.length, sentiment_complessivo: s, aspetti };
});

// --- segnalazioni
const segnalate = tutte.filter((r) => r.needs_attention && r.stato !== 'duplicato');
const ORD = { alta: 0, media: 1, bassa: 2 };
const perCategoria = {};
for (const r of segnalate) for (const s of r.segnalazioni) perCategoria[s.categoria] = (perCategoria[s.categoria] ?? 0) + 1;
const perPriorita = { alta: 0, media: 0, bassa: 0 };
for (const r of segnalate) perPriorita[r.priorita]++;
const segnalazioni = {
  totale: segnalate.length,
  pct_sul_totale: pct(segnalate.length, tutte.filter((r) => r.stato !== 'duplicato').length),
  per_priorita: perPriorita,
  per_categoria: perCategoria,
  solo_per_voto_basso: segnalate.filter((r) => r.segnalazioni.length === 0 && r.rating !== null && r.rating <= ctx.voto.basso_fino_a).length,
  per_periodo: periodi.map((p) => ({
    periodo: p.periodo,
    segnalate: segnalate.filter((r) => r.anno >= p.dal_anno && r.anno <= p.al_anno).length,
    segnalate_priorita_alta: segnalate.filter((r) => r.anno >= p.dal_anno && r.anno <= p.al_anno && r.priorita === 'alta').length,
  })),
  elenco: segnalate
    .sort((a, b) => ORD[a.priorita] - ORD[b.priorita] || (b.published_date ?? '').localeCompare(a.published_date ?? ''))
    .map((r) => ({
      review_id: r.review_id,
      published_date: r.published_date,
      rating: r.rating,
      priorita: r.priorita,
      categorie: [...new Set(r.segnalazioni.map((s) => s.categoria))],
      attention_reason: r.attention_reason,
    })),
};

const lingue = {};
for (const r of valide) lingue[r.language] = (lingue[r.language] ?? 0) + 1;
const date = valide.map((r) => r.published_date).filter(Boolean).sort();

// --- l'elenco fisso degli aspetti va rivisto?
// I temi fuori elenco sono la categoria «altro» del sistema. Si confronta la quota
// di recensioni con temi fuori elenco con la linea di base salvata nell'elenco fisso
// (test su due proporzioni, regola dei 2 errori standard) e si cercano i temi fuori
// elenco abbastanza frequenti da meritare un aspetto (almeno il 2% delle recensioni).
// Se una delle due condizioni scatta, l'elenco va rivisto da una persona (nuova versione).
const elencoAspetti = (() => {
  const conFuori = valide.filter((r) => (r.unmapped ?? []).length > 0).length;
  const base = tax.linea_di_base;
  let confronto = null;
  if (base?.recensioni) {
    const t = dueProporzioni(conFuori, N, base.recensioni_con_temi_fuori_elenco, base.recensioni);
    confronto = { pct_oggi: pct(conFuori, N), pct_linea_di_base: base.pct, z: t.z, sopra_la_linea_di_base: t.z >= 2 };
  }
  const conteggio = new Map();
  for (const r of valide) for (const u of new Set(r.unmapped ?? [])) conteggio.set(u, (conteggio.get(u) ?? 0) + 1);
  const soglia = Math.max(5, Math.ceil(0.02 * N));
  const candidati = [...conteggio].filter(([, n]) => n >= soglia).sort((a, b) => b[1] - a[1])
    .map(([tema, n]) => ({ tema, recensioni: n, pct: pct(n, N) }));
  const fisso = tax.origine_aspetti === 'elenco fisso';
  return {
    versione: tax.versione_aspetti,
    origine: tax.origine_aspetti,
    recensioni_con_temi_fuori_elenco_pct: pct(conFuori, N),
    confronto_con_la_linea_di_base: confronto,
    soglia_temi_candidati_recensioni: soglia,
    temi_candidati: candidati,
    da_rivedere: fisso && (!!confronto?.sopra_la_linea_di_base || candidati.length > 0),
    regola: "da rivedere se la quota di recensioni con temi fuori elenco supera la linea di base di almeno 2 errori standard, oppure se un tema fuori elenco compare in almeno il 2% delle recensioni",
  };
})();

// --- andamento mese per mese (mesi del calendario, non uniti come i periodi qui sopra)
// Per ogni mese dal primo all'ultimo con recensioni (anche i mesi vuoti restano nella serie, cosi' «il mese prima»
// e' sempre quello del calendario): recensioni, voto medio, sentiment. Confronto con il mese prima sulla quota di
// recensioni negative: test su due proporzioni solo se tutti e due i mesi hanno almeno 20 recensioni (sotto:
// «pochi dati», numeri senza verdetto), correzione di Benjamini-Hochberg (FDR 10%) su tutti i confronti fatti.
// L'archivio e' storico: la serie finisce all'ultimo mese con dati; il primo e l'ultimo mese sono segnati se i dati
// li coprono solo in parte.
const MIN_RECENSIONI_CONFRONTO = 20;
const periodiCalendario = (() => {
  const conData = valide.filter((r) => r.published_date);
  if (!conData.length) return null;
  const giorni = conData.map((r) => String(r.published_date).slice(0, 10)).sort();
  const primaData = giorni[0], ultimaData = giorni[giorni.length - 1];
  const successivo = (k) => { const [a, m] = k.split('-').map(Number); return m === 12 ? `${a + 1}-01` : `${a}-${String(m + 1).padStart(2, '0')}`; };
  const ultimoGiorno = (k) => { const [a, m] = k.split('-').map(Number); return new Date(Date.UTC(a, m, 0)).toISOString().slice(0, 10); };
  const gruppi = new Map();
  for (const r of conData) {
    const k = String(r.published_date).slice(0, 7);
    if (!gruppi.has(k)) gruppi.set(k, []);
    gruppi.get(k).push(r);
  }
  const primo = primaData.slice(0, 7), ultimo = ultimaData.slice(0, 7);
  const periodi = [];
  for (let k = primo; k <= ultimo; k = successivo(k)) {
    const l = gruppi.get(k) ?? [];
    const neg = l.filter((r) => r.overall_sentiment === 'negative').length;
    periodi.push({
      periodo: k,
      in_corso: false,
      dati_solo_dal: k === primo && primaData > `${k}-01` ? primaData : null,
      dati_fino_al: k === ultimo && ultimaData < ultimoGiorno(k) ? ultimaData : null,
      recensioni: l.length,
      voto_medio: media(l.filter((r) => r.rating !== null).map((r) => r.rating)),
      positive: l.filter((r) => r.overall_sentiment === 'positive').length,
      negative: neg,
      miste: l.filter((r) => r.overall_sentiment === 'mixed').length,
      neutre: l.filter((r) => r.overall_sentiment === 'neutral').length,
      pct_negative: pct(neg, l.length),
    });
  }
  const confronti = [];
  periodi.forEach((p, i) => {
    if (i === 0) return;
    const q = periodi[i - 1];
    const c = { periodo_prima: q.periodo, pct_negative_prima: q.pct_negative, differenza_punti: p.pct_negative !== null && q.pct_negative !== null ? Math.round(10 * (p.pct_negative - q.pct_negative)) / 10 : null };
    if (p.recensioni >= MIN_RECENSIONI_CONFRONTO && q.recensioni >= MIN_RECENSIONI_CONFRONTO) {
      Object.assign(c, dueProporzioni(p.negative, p.recensioni, q.negative, q.recensioni));
      c.p_value = Number(c.p_value.toPrecision(3));
      confronti.push(c);
    } else {
      c.esito = 'pochi dati';
    }
    p.confronto = c;
  });
  // Benjamini-Hochberg (FDR 10%) sui confronti fatti
  const ordinati = [...confronti].sort((a, b) => a.p_value - b.p_value);
  let soglia = -1;
  ordinati.forEach((x, i) => { if (x.p_value <= ((i + 1) / ordinati.length) * 0.1) soglia = i; });
  ordinati.forEach((x, i) => { x.significativo = i <= soglia; x.esito = x.significativo ? 'oltre il rumore' : 'entro il rumore'; });
  return {
    regola: `quota di recensioni negative di ogni mese contro il mese prima; test su due proporzioni solo con almeno ${MIN_RECENSIONI_CONFRONTO} recensioni in tutti e due i mesi, correzione Benjamini-Hochberg (FDR 10%); dal ${primaData} al ${ultimaData}`,
    mesi: [{ piattaforma: 'tutte', periodi }],
  };
})();

const aggregazione = {
  meta: {
    generato_il: new Date().toISOString(),
    modello: cfg.model,
    file_input: cfg.input_file,
    righe_nel_file: fileInfo.righe_nel_file,
    recensioni_in_output: tutte.length,
    recensioni_aggregate: N,
    escluse_dall_aggregazione: {
      duplicati: tutte.filter((r) => r.stato === 'duplicato').length,
      vuote: tutte.filter((r) => r.stato === 'vuota').length,
      analisi_fallita: tutte.filter((r) => r.stato === 'fallita').length,
      sospette_di_manipolazione: tutte.filter((r) => r.sospetta && r.stato !== 'duplicato').length,
    },
    prima_data: date[0] ?? null,
    ultima_data: date[date.length - 1] ?? null,
    elenco_aspetti: elencoAspetti,
    regola_periodi: `anni di pubblicazione uniti finche' ogni periodo ha almeno ${cfg.min_reviews_per_period} recensioni`,
    definizioni: {
      menzioni: "recensioni che esprimono un giudizio sull'aspetto (al massimo 1 per recensione)",
      pct_recensioni_che_lo_apprezzano: "recensioni con giudizio positivo sull'aspetto / recensioni aggregate del periodo x 100",
      pct_recensioni_che_lo_criticano: "recensioni con giudizio negativo sull'aspetto / recensioni aggregate del periodo x 100",
      pct_positive_su_menzioni: "giudizi positivi / menzioni x 100",
      pct_negative_su_menzioni: "giudizi negativi / menzioni x 100",
      saldo: '(positive - negative) / menzioni, da -1 a +1',
      piu_apprezzati: 'ordinati per numero di recensioni che apprezzano l\'aspetto',
      piu_criticati: 'ordinati per numero di recensioni che criticano l\'aspetto',
      per_tasso: `ordinati per quota sulle menzioni, solo aspetti con almeno ${minM} menzioni`,
      per_lingua: 'ogni lingua con almeno 15 recensioni contro tutte le altre, quota di recensioni negative o miste; significativo dopo Benjamini-Hochberg (FDR 10%)',
      andamento: 'ultimo periodo contro i precedenti; significativo = test su due proporzioni con correzione Benjamini-Hochberg (FDR 10%)',
    },
  },
  sentiment_complessivo: contaSentiment(valide),
  voto_medio: media(valide.filter((r) => r.rating !== null).map((r) => r.rating)),
  lingue,
  per_lingua: perLingua,
  aspetti: Object.values(statTotali),
  classifiche,
  periodi,
  andamento,
  serie_annuale: serieAnnuale,
  segnalazioni,
  periodi_di_calendario: periodiCalendario,
};

return [{ json: { aggregazione, info_analisi: infoAnalisi } }];

// FATTI PER IL DIGEST
// Il codice calcola i fatti e scrive le frasi con i numeri. Il modello riceve i
// fatti e restituisce solo commenti a parole (senza cifre) e citazioni: il digest
// lo monta il nodo "Verifica digest", che inserisce le frasi con i numeri.
const cfg = $('Configurazione').first().json;
const ctx = $('Valida contesto').first().json;
const A = $input.first().json.aggregazione;
const recensioni = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json]));
const analisi = new Map($('Valida e completa').all().map((i) => [i.json.review_id, i.json]));

const intero = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const perc = (x) => (x === null || x === undefined ? null : x > 0 && x < 1 ? String(x).replace('.', ',') + '%' : Math.round(x) + '%');
const dec = (x) => String(x).replace('.', ',');
const nome = (id) => A.aspetti.find((a) => a.aspect === id)?.nome ?? id;

const NOMI_PERSONA = /\b(Mr|Mrs|Ms|Miss|Mme|Dr|Sr|Sra|Herr|Frau|Sig|Signor|Signora)\.?\s+[A-Z][a-z]+/;

function candidati(aspect, sentimentAspetto, overallAmmessi, quanti) {
  const lista = [];
  for (const r of analisi.values()) {
    if (r.sospetta || !['ok', 'ritentata'].includes(r.stato)) continue;
    if (!overallAmmessi.includes(r.overall_sentiment)) continue;
    if (!r.aspects.some((x) => x.aspect === aspect && x.sentiment === sentimentAspetto)) continue;
    const rec = recensioni.get(r.review_id);
    if (!rec || rec.text.length < 80 || rec.text.length > 700 || NOMI_PERSONA.test(rec.text)) continue;
    if (/<[A-Z_]+>/.test(rec.text)) continue; // testi con dati oscurati: meglio non citarli
    lista.push({ r, rec });
  }
  // prima l'inglese (leggibile dalla direzione), poi le piu' recenti
  lista.sort((a, b) => (a.r.language === 'en' ? 0 : 1) - (b.r.language === 'en' ? 0 : 1) || (b.rec.published_date ?? '').localeCompare(a.rec.published_date ?? ''));
  return lista.slice(0, quanti).map(({ r, rec }) => ({
    review_id: r.review_id,
    data: rec.published_date,
    voto: `${rec.rating} su ${ctx.voto.massimo}`,
    lingua: r.language,
    testo: rec.text,
  }));
}

const top = (lista, n) => lista.slice(0, n);

// articolo davanti a una percentuale (il 12%, l'11%, lo 0,4%) e preposizioni articolate
function art(p) {
  const n = String(p);
  if (/^0/.test(n)) return 'lo ' + n;
  if (/^(8|11(?![\d])|1(?![\d])|1,)/.test(n)) return "l'" + n;
  return 'il ' + n;
}
function prep(p, base) {
  const a = art(p);
  const forme = { da: { 'il ': 'dal ', "l'": "dall'", 'lo ': 'dallo ' }, a: { 'il ': 'al ', "l'": "all'", 'lo ': 'allo ' } };
  for (const [k, v] of Object.entries(forme[base])) if (a.startsWith(k)) return v + a.slice(k.length);
  return a;
}
const misuraTesto = (m) => (m === 'pct_recensioni_che_lo_criticano' ? 'negativo' : 'positivo');

// la prova di una segnalazione e' stata accettata anche se quasi identica al testo:
// al digest si passa invece la frase ESATTA del testo che le somiglia di piu',
// cosi' il modello puo' citarla parola per parola
function provaEsatta(evidenza, testo) {
  if (!evidenza || !testo) return null;
  const pulito = (s) => s.toLowerCase().replace(/\s+/g, ' ').trim();
  if (pulito(testo).includes(pulito(evidenza))) {
    const i = pulito(testo).indexOf(pulito(evidenza));
    // ricostruisce lo stesso pezzo con gli spazi originali
    const testoSpazi = testo.replace(/\s+/g, ' ');
    return testoSpazi.slice(i, i + pulito(evidenza).length).trim();
  }
  const parole = new Set(pulito(evidenza).match(/[\p{L}\p{N}]+/gu) ?? []);
  const frasi = testo.split(/(?<=[.!?])\s+|\n+/).map((f) => f.replace(/\s+/g, ' ').trim()).filter((f) => f.length > 10);
  let migliore = null, punti = 0;
  for (const f of frasi) {
    const p = (pulito(f).match(/[\p{L}\p{N}]+/gu) ?? []).filter((w) => parole.has(w)).length;
    if (p > punti) { punti = p; migliore = f; }
  }
  return migliore ? migliore.split(' ').slice(0, 30).join(' ') : null;
}

// parole che indicano l'aspetto in una frase (dai temi raggruppati): servono a
// scegliere, nel digest di riserva, una frase che parla davvero di quell'aspetto
const tassonomia = $('Valida tassonomia').first().json.aspetti;
function paroleChiave(aspect) {
  const a = tassonomia.find((x) => x.aspect === aspect);
  const parole = [...(a?.temi_raggruppati ?? []), aspect.replace(/_/g, ' ')].join(' ').toLowerCase().match(/[a-z]{4,}/g) ?? [];
  const generiche = new Set(['quality', 'service', 'services', 'experience', 'overall', 'general', 'level', 'value']);
  return [...new Set(parole)].filter((p) => !generiche.has(p));
}
const S = A.sentiment_complessivo;
const anni = [A.meta.prima_data?.slice(0, 4), A.meta.ultima_data?.slice(0, 4)];

const significativi = A.andamento.filter((x) => x.significativo);
const fatti = {
  // FRASI CON I NUMERI: le scrive il codice, il modello le copia identiche.
  // Cosi' un numero non puo' cambiare significato (es. una quota sul totale
  // presentata come quota su chi parla dell'aspetto).
  frase_sintesi: `Sono state analizzate ${intero(A.meta.recensioni_aggregate)} recensioni pubblicate dal ${anni[0]} al ${anni[1]}. Il voto medio e' ${dec(A.voto_medio)} su ${ctx.voto.massimo}. ${art(perc(S.positive.pct)).replace(/^./, (c) => c.toUpperCase())} delle recensioni e' positivo, ${art(perc(S.mixed.pct))} misto, ${art(perc(S.negative.pct))} negativo e ${art(perc(S.neutral.pct))} neutro.`,
  // numeri senza ambiguita' che si possono ripetere anche fuori dalle frasi
  recensioni_analizzate: intero(A.meta.recensioni_aggregate),
  dal_anno: anni[0],
  al_anno: anni[1],
  escluse_dai_conteggi: A.meta.escluse_dall_aggregazione,
  aspetti_piu_apprezzati: top(A.classifiche.piu_apprezzati, 5).map((x) => ({
    aspetto: x.nome,
    frase_numeri: `${intero(x.recensioni_positive)} recensioni su ${intero(A.meta.recensioni_aggregate)} ne danno un giudizio positivo (${art(perc(x.pct_recensioni_che_lo_apprezzano))} del totale); tra le ${intero(x.menzioni)} recensioni che ne parlano, i giudizi positivi sono ${art(perc(x.pct_positive_su_menzioni))}`,
  })),
  aspetti_piu_criticati: top(A.classifiche.piu_criticati, 5).map((x) => ({
    aspetto: x.nome,
    frase_numeri: `${intero(x.recensioni_negative)} recensioni su ${intero(A.meta.recensioni_aggregate)} ne danno un giudizio negativo (${art(perc(x.pct_recensioni_che_lo_criticano))} del totale); tra le ${intero(x.menzioni)} recensioni che ne parlano, i giudizi negativi sono ${art(perc(x.pct_negative_su_menzioni))}`,
  })),
  aspetti_piu_divisivi: top(A.classifiche.piu_criticati_per_tasso, 3).map((x) => ({
    aspetto: x.nome,
    frase_numeri: `tra le ${intero(x.menzioni)} recensioni che ne parlano, i giudizi negativi sono ${art(perc(x.pct_negative_su_menzioni))}`,
  })),
  periodi: A.periodi.map((p) => ({
    periodo: p.periodo,
    frase_numeri: `nel periodo ${p.periodo} (${intero(p.recensioni)} recensioni) il voto medio e' ${dec(p.voto_medio)} su ${ctx.voto.massimo}, con ${art(perc(p.sentiment_complessivo.positive.pct))} di recensioni positive e ${art(perc(p.sentiment_complessivo.negative.pct))} di negative`,
    piu_apprezzati: p.piu_apprezzati.slice(0, 3).map(nome),
    piu_criticati: p.piu_criticati.slice(0, 3).map(nome),
  })),
  // una sola frase per aspetto e per periodo di confronto, con critiche e apprezzamenti
  // insieme: il modello tende a unire due frasi sullo stesso aspetto, e cosi' non serve
  cambiamenti_significativi: (() => {
    const gruppi = new Map();
    for (const x of significativi) {
      const k = x.nome + '|' + x.periodo_di_confronto;
      if (!gruppi.has(k)) gruppi.set(k, { aspetto: x.nome, confronto: x.periodo_di_confronto, ultimo: x.ultimo_periodo, pezzi: [] });
      gruppi.get(k).pezzi.push(x);
    }
    return [...gruppi.values()].map((g) => {
      const pezzo = (x) => `le recensioni con giudizio ${misuraTesto(x.misura)} passano ${prep(perc(x.valore_periodo_di_confronto), 'da')} ${prep(perc(x.valore_ultimo_periodo), 'a')}`;
      const ordinati = [...g.pezzi].sort((a, b) => (a.misura < b.misura ? -1 : 1));
      return {
        aspetto: g.aspetto,
        frase_numeri: `${g.aspetto}, dal ${g.confronto} al ${g.ultimo}: ${ordinati.map(pezzo).join(' e ')}`,
      };
    });
  })(),
  // numeri senza ambiguita', ammessi anche fuori dalle frasi
  confronti_nel_tempo_eseguiti: intero(A.andamento.length),
  confronti_nel_tempo_significativi: intero(significativi.length),
  frase_segnalate: `Le recensioni segnalate sono ${intero(A.segnalazioni.totale)} (${art(perc(A.segnalazioni.pct_sul_totale))} del totale): ${intero(A.segnalazioni.per_priorita.alta)} con priorita' alta, ${intero(A.segnalazioni.per_priorita.media)} media e ${intero(A.segnalazioni.per_priorita.bassa)} bassa.`,
  segnalate_da_mostrare: A.segnalazioni.elenco.slice(0, 8).map((s) => ({
    review_id: s.review_id,
    data: s.published_date,
    voto: s.rating === null ? null : `${s.rating} su ${ctx.voto.massimo}`,
    priorita: s.priorita,
    motivo: s.attention_reason,
    prova: provaEsatta(analisi.get(s.review_id)?.segnalazioni?.[0]?.evidenza, recensioni.get(s.review_id)?.text),
  })),
  lingue_con_abbastanza_recensioni: A.per_lingua.filter((l) => l.confronto_con_le_altre_lingue).map((l) => ({
    lingua: l.lingua,
    recensioni: intero(l.recensioni),
    negative_o_miste: perc(l.confronto_con_le_altre_lingue.valore_lingua),
  })),
  differenze_tra_lingue_significative: A.per_lingua.filter((l) => l.confronto_con_le_altre_lingue?.significativo).map((l) => ({
    lingua: l.lingua,
    frase_numeri: `nelle recensioni in lingua ${l.lingua} le negative o miste sono ${art(perc(l.confronto_con_le_altre_lingue.valore_lingua))}, contro ${art(perc(l.confronto_con_le_altre_lingue.valore_altre_lingue))} nelle altre lingue`,
  })),
  citazioni_disponibili: [
    ...top(A.classifiche.piu_apprezzati, 3).map((x) => ({ per: `apprezzato: ${x.nome}`, parole_chiave: paroleChiave(x.aspect), recensioni: candidati(x.aspect, 'positive', ['positive'], 3) })),
    ...top(A.classifiche.piu_criticati, 3).map((x) => ({ per: `criticato: ${x.nome}`, parole_chiave: paroleChiave(x.aspect), recensioni: candidati(x.aspect, 'negative', ['negative', 'mixed'], 3) })),
  ],
};

const SYSTEM = `Sei un analista che scrive per ${ctx.lettori_dei_risultati}: le recensioni riguardano ${ctx.oggetto_recensito} e sono scritte da ${ctx.autori_delle_recensioni}. Ricevi i fatti in JSON, gia' calcolati. I numeri, gli elenchi e i titoli li inserisce il sistema: tu scrivi SOLO i commenti a parole e scegli le citazioni, in ${ctx.lingua_del_digest} semplice, per chi non e' tecnico.

Restituisci un JSON con questi campi:
- sintesi: da due a quattro frasi su che cosa emerge nel complesso (che cosa piace, che cosa si critica, come cambiano le cose). Aggiungi una frase sulle lingue: se "differenze_tra_lingue_significative" e' vuoto, di' che le recensioni nelle diverse lingue non mostrano differenze distinguibili dal caso.
- commento_apprezzati: due o tre frasi sugli aspetti in "aspetti_piu_apprezzati".
- commento_criticati: due o tre frasi sugli aspetti in "aspetti_piu_criticati" e "aspetti_piu_divisivi". Spiega la differenza tra un aspetto criticato da molte recensioni in assoluto e uno criticato da una parte grande di chi ne parla.
- commento_tempo: da due a quattro frasi sui "cambiamenti_significativi". Se e' vuoto, di' che i cambiamenti tra periodi non sono distinguibili dal caso. Parla solo dei cambiamenti significativi e non spiegarne le cause.
- commento_segnalate: da una a tre frasi sui temi delle recensioni da guardare.
- citazioni: da tre a sei citazioni, almeno una per la sezione "apprezzati", una per "criticati" e una per "segnalate". Per ognuna: sezione, review_id, testo copiato parola per parola da un campo "testo" o "prova" dei fatti (frasi consecutive, al massimo 30 parole), traduzione in ${ctx.lingua_del_digest} (stringa vuota se la citazione e' gia' in ${ctx.lingua_del_digest}).

Regole obbligatorie:
1. Nei commenti NESSUNA cifra: niente numeri, percentuali, anni o conteggi. Descrivi a parole (per esempio "la maggior parte", "aumentano", "piu' di prima", "nell'ultimo periodo").
2. Nei commenti niente virgolette « »: le citazioni vanno solo nel campo "citazioni".
3. Nomi degli aspetti come scritti nei fatti.
4. Nessun nome di persona; non scegliere citazioni che ne contengono.
5. Nessuna informazione che non sia nei fatti.`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['sintesi', 'commento_apprezzati', 'commento_criticati', 'commento_tempo', 'commento_segnalate', 'citazioni'],
  properties: {
    sintesi: { type: 'string' },
    commento_apprezzati: { type: 'string' },
    commento_criticati: { type: 'string' },
    commento_tempo: { type: 'string' },
    commento_segnalate: { type: 'string' },
    citazioni: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['sezione', 'review_id', 'testo', 'traduzione'],
        properties: {
          sezione: { type: 'string', enum: ['apprezzati', 'criticati', 'segnalate'] },
          review_id: { type: 'string' },
          testo: { type: 'string' },
          traduzione: { type: 'string' },
        },
      },
    },
  },
};

return [{
  json: {
    fatti,
    body: {
      model: cfg.model,
      temperature: 0,
      seed: cfg.seed,
      max_tokens: 2500,
      response_format: { type: 'json_schema', json_schema: { name: 'digest', strict: true, schema: SCHEMA } },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: JSON.stringify(fatti, null, 1) },
      ],
    },
  },
}];

// VERIFICA E COMPOSIZIONE DEL DIGEST
// Il digest lo monta il CODICE: titoli, frasi con i numeri (scritte nel nodo dei
// fatti), elenchi, recensioni da guardare. Dal modello arrivano solo i commenti a
// parole, sezione per sezione, e le citazioni. Cosi' ogni numero del digest e'
// scritto dal codice, per costruzione, e non puo' cambiare significato.
// Controlli sulla parte del modello:
// - nei commenti nessuna cifra e nessuna virgoletta « »;
// - ogni citazione copiata parola per parola dalla recensione indicata;
// - identificativi esistenti e almeno una citazione per le sezioni principali.
// Se un controllo fallisce, il modello riceve i problemi e corregge (fino a 2 volte).
// Se non basta, il digest esce senza i commenti del modello (versione di riserva).
const helpers = this.helpers;
const usoToken = []; // token delle correzioni del digest
const cfg = $('Configurazione').first().json;
const { fatti, body } = $('Fatti per il digest').first().json;
const testi = new Map($('Recensioni pronte').all().map((i) => [i.json.review_id, i.json.title + '\n' + i.json.text]));

const norm = (s) =>
  String(s ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[“”„"]/g, '"')
    .replace(/[‘’`´]/g, "'")
    .replace(/…/g, '...')
    .replace(/\s+/g, ' ')
    .trim();
const maiusc = (s) => String(s).replace(/^./, (c) => c.toUpperCase());
const SEZIONI = ['apprezzati', 'criticati', 'segnalate'];
const COMMENTI = ['sintesi', 'commento_apprezzati', 'commento_criticati', 'commento_tempo', 'commento_segnalate'];

function leggi(content) {
  try {
    return JSON.parse(content);
  } catch (e) {
    return null;
  }
}

function controlla(o) {
  if (!o) return ['la risposta non e\' un JSON valido'];
  const problemi = [];
  for (const k of COMMENTI) {
    const t = String(o[k] ?? '').trim();
    if (!t) problemi.push(`il campo ${k} e' vuoto`);
    const cifre = t.match(/\d+/g);
    if (cifre) problemi.push(`il campo ${k} contiene cifre (${cifre.slice(0, 5).join(', ')}): descrivi a parole, senza numeri ne' anni`);
    if (/[«»]/.test(t)) problemi.push(`il campo ${k} contiene virgolette « »: le citazioni vanno solo nel campo "citazioni"`);
  }
  const cit = Array.isArray(o.citazioni) ? o.citazioni : [];
  for (const s of SEZIONI) if (!cit.some((c) => c.sezione === s)) problemi.push(`manca una citazione per la sezione "${s}"`);
  for (const c of cit) {
    const testo = testi.get(c.review_id);
    if (!testo) {
      problemi.push(`la citazione per "${c.sezione}" indica un identificativo inesistente (${c.review_id})`);
      continue;
    }
    const pezzi = norm(c.testo).split(/\.{3,}/).map((p) => p.trim().replace(/^["'.,;:\s]+|["',;:\s]+$/g, '')).filter((p) => p.length > 2);
    if (!pezzi.length || !pezzi.every((p) => norm(testo).includes(p))) {
      problemi.push(`la citazione «${String(c.testo).slice(0, 60)}...» non e' copiata parola per parola dalla recensione ${c.review_id}: copia frasi consecutive senza cambiare parole, oppure segna con "..." le parti saltate`);
    }
    if (String(c.testo).split(/\s+/).length > 40) problemi.push(`la citazione della recensione ${c.review_id} supera 30 parole`);
    const numeriCitazione = new Set(String(c.testo).match(/\d+/g) ?? []);
    for (const n of String(c.traduzione ?? '').match(/\d+/g) ?? []) {
      if (!numeriCitazione.has(n)) problemi.push(`la traduzione della citazione ${c.review_id} contiene il numero ${n}, che non e' nella citazione`);
    }
  }
  return problemi;
}

// --- citazioni per la versione di riserva: una frase della recensione che contiene una parola dell'aspetto
function fraseSullAspetto(testo, paroleChiave) {
  const frasi = testo.split(/(?<=[.!?])\s+|\n+/).map((s) => s.trim()).filter((s) => s.split(/\s+/).length >= 4);
  const scelta = frasi.find((s) => paroleChiave.some((k) => s.toLowerCase().includes(k))) ?? frasi[0] ?? testo;
  return scelta.split(/\s+/).slice(0, 30).join(' ');
}
function citazioniDiRiserva(sezione) {
  const giaCitate = new Set();
  return fatti.citazioni_disponibili
    .filter((c) => c.per.startsWith(sezione === 'apprezzati' ? 'apprezzato' : 'criticato'))
    .slice(0, 2)
    .map((c) => {
      const r = c.recensioni.find((x) => !giaCitate.has(x.review_id));
      if (!r) return null;
      giaCitate.add(r.review_id);
      return { sezione, review_id: r.review_id, testo: fraseSullAspetto(r.testo, c.parole_chiave ?? []), traduzione: '' };
    })
    .filter(Boolean);
}

// --- composizione del digest
function componi(o) {
  const f = fatti;
  const r = [];
  const citazioni = (sezione) => {
    const lista = o ? (o.citazioni ?? []).filter((c) => c.sezione === sezione) : sezione === 'segnalate' ? [] : citazioniDiRiserva(sezione);
    return lista.flatMap((c) => [`> «${c.testo}» (${c.review_id})${c.traduzione ? ` [${c.traduzione}]` : ''}`, '']);
  };
  r.push('# Digest delle recensioni', '');

  r.push('## In sintesi', '', f.frase_sintesi, '');
  for (const l of f.differenze_tra_lingue_significative ?? []) r.push(maiusc(l.frase_numeri) + '.', '');
  if (o) r.push(o.sintesi.trim(), '');
  else if (!(f.differenze_tra_lingue_significative ?? []).length) r.push('Le recensioni nelle diverse lingue non mostrano differenze distinguibili dal caso.', '');

  r.push("## Cosa apprezzano di piu'", '');
  for (const x of f.aspetti_piu_apprezzati) r.push(`- **${x.aspetto}**: ${x.frase_numeri}.`);
  r.push('');
  if (o) r.push(o.commento_apprezzati.trim(), '');
  r.push(...citazioni('apprezzati'));

  r.push("## Cosa criticano di piu'", '');
  for (const x of f.aspetti_piu_criticati) r.push(`- **${x.aspetto}**: ${x.frase_numeri}.`);
  r.push('');
  if (f.aspetti_piu_divisivi.length) {
    r.push("Gli aspetti piu' divisivi, cioe' criticati da una parte grande di chi ne parla:", '');
    for (const x of f.aspetti_piu_divisivi) r.push(`- **${x.aspetto}**: ${x.frase_numeri}.`);
    r.push('');
  }
  if (o) r.push(o.commento_criticati.trim(), '');
  r.push(...citazioni('criticati'));

  r.push('## Come cambiano le cose nel tempo', '');
  r.push(`Le recensioni sono raggruppate in periodi con abbastanza recensioni per un confronto. Sono stati fatti ${f.confronti_nel_tempo_eseguiti} confronti tra l'ultimo periodo e i precedenti: ${f.confronti_nel_tempo_significativi} risultano significativi dopo la correzione per confronti multipli.`, '');
  for (const x of f.cambiamenti_significativi) r.push(`- ${x.frase_numeri}.`);
  if (f.cambiamenti_significativi.length) r.push('');
  for (const p of f.per_piattaforma ?? []) {
    r.push(`Versioni dell'app su ${p.piattaforma}:`, '');
    for (const v of p.versioni) {
      r.push(v.nota ? `- versione ${v.versione}: ${v.recensioni} recensioni, ${v.nota}.` : `- versione ${v.versione}: ${v.recensioni} recensioni, voto medio ${v.voto_medio}, positive ${v.positive}, negative ${v.negative}.`);
    }
    for (const x of p.cambiamenti_ultima_versione) r.push(`- ${x.aspetto}: ${x.misura} in ${x.direzione}, ${x.valore_ultima_versione} nella versione ${x.ultima_versione} contro ${x.valore_di_confronto} nelle versioni precedenti.`);
    r.push('');
  }
  if (o) r.push(o.commento_tempo.trim(), '');
  r.push('Andamento per periodo:', '');
  for (const p of f.periodi) r.push(`- ${maiusc(p.frase_numeri)}.`);
  r.push('');

  r.push('## Recensioni da guardare', '', f.frase_segnalate, '');
  for (const s of f.segnalate_da_mostrare) r.push(`- ${s.review_id} (${s.data}${s.voto ? `, voto ${s.voto}` : ''}, priorita' ${s.priorita}): ${s.motivo}`);
  r.push('');
  if (o) r.push(o.commento_segnalate.trim(), '');
  r.push(...citazioni('segnalate'));

  r.push('## Come sono stati ottenuti questi numeri', '');
  r.push("Ogni recensione e' stata letta da un modello linguistico, nella sua lingua, che ne ha indicato il giudizio complessivo e il giudizio sugli aspetti di un elenco fisso. Tutti i numeri di questo testo sono conteggi calcolati dal sistema su quelle analisi; i cambiamenti nel tempo sono indicati solo quando superano la soglia statistica dopo la correzione per confronti multipli. Le segnalazioni seguono criteri fissati in anticipo e ognuna ha una frase di prova presa dalla recensione.");
  r.push('');
  r.push(o
    ? "I commenti a parole e la scelta delle citazioni sono del modello; ogni citazione e' stata controllata parola per parola sulla recensione originale."
    : "Questa versione non contiene i commenti del modello, perche' non hanno superato i controlli automatici; le citazioni sono scelte dal sistema.");
  return r.join('\n');
}

// --- chiamata al modello con le correzioni
async function chiedi(messaggi) {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: cfg.base_url + '/chat/completions',
    headers: { Authorization: 'Bearer ' + $env.OPENAI_API_KEY },
    body: { ...body, messages: messaggi },
    json: true,
    timeout: 180000,
  });
  if (res.usage) usoToken.push(res.usage);
  return String(res.choices?.[0]?.message?.content ?? '');
}

let risposta = String($input.first().json?.choices?.[0]?.message?.content ?? '');
let o = leggi(risposta);
let problemi = controlla(o);
const tentativi = [{ tentativo: 1, ok: problemi.length === 0, problemi }];
let messaggi = [...body.messages];
for (let t = 2; t <= 3 && problemi.length; t++) {
  messaggi = [
    ...messaggi,
    { role: 'assistant', content: risposta || '(vuoto)' },
    { role: 'user', content: 'La risposta non supera i controlli automatici. Correggi questi problemi e restituisci di nuovo il JSON completo:\n- ' + problemi.join('\n- ') },
  ];
  try {
    risposta = await chiedi(messaggi);
    o = leggi(risposta);
    problemi = controlla(o);
  } catch (e) {
    problemi = ['errore di chiamata al modello: ' + e.message];
  }
  tentativi.push({ tentativo: t, ok: problemi.length === 0, problemi });
}

const usaModello = problemi.length === 0;
const riserva = componi(null);
return [{
  json: {
    digest: usaModello ? componi(o) : riserva,
    origine: usaModello ? 'modello' : 'riserva_controlli_non_superati',
    verifica: { tentativi, esito_finale: { ok: usaModello, problemi } },
    uso_token: usoToken,
    digest_riserva: riserva,
    esito_riserva: { ok: true, nota: 'composto dal codice: numeri dalle frasi dei fatti, citazioni scelte dal sistema' },
    // risposta del modello scartata, conservata per capire perche'
    ultimo_testo_modello: usaModello ? null : risposta,
  },
}];

// USA IL DIGEST DI RISERVA
// Si arriva qui solo se il guardrail di uscita ha trovato nel digest dati
// personali, link, chiavi o nomi di persone. Il testo non viene pubblicato:
// si usa il digest di riserva, scritto senza modello dagli stessi fatti.
const v = $('Verifica digest').first().json;
const controlli = ($input.first().json.checks ?? []).filter((c) => c.triggered);
return [{
  json: {
    digest: v.digest_riserva,
    origine: 'riserva_guardrail_uscita',
    guardrail_uscita: controlli.map((c) => ({ controllo: c.name, info: c.info ?? null, confidenza: c.confidenceScore ?? null })),
  },
}];

// PREPARA I FILE DI OUTPUT
// Ultimo controllo dello schema di ogni recensione, poi scrive:
//   recensioni_analizzate.json   un oggetto per recensione, nello schema richiesto
//   recensioni_analizzate.jsonl  lo stesso, una riga per recensione
//   aspetti.json                 elenco finale degli aspetti con descrizione
//   aggregazione.json            conteggi, classifiche, periodi, andamento
//   digest.md                    testo per la direzione
//   esecuzione.json              diagnostica: guardrail, ritentativi, scarti, verifiche
//   recensioni_diagnostica.jsonl dettaglio per recensione (segnalazioni con prova, temi fuori elenco)
const cfg = $('Configurazione').first().json;
const tax = $('Valida tassonomia').first().json;
// con l'elenco fisso la scoperta non gira: questi nodi possono non avere dati
let temi = { temi: [] };
let campione = [];
try {
  temi = $('Raccogli temi').first().json;
  campione = $('Campione per scoperta aspetti').all().flatMap((i) => i.json.ids);
} catch (e) {
  // elenco fisso
}
const pronte = $('Recensioni pronte').all().map((i) => i.json);
const analisi = $('Valida e completa').all().map((i) => i.json);
const { aggregazione, info_analisi } = $('Aggregazione').first().json;
const verifica = $('Verifica digest').first().json;

// il digest arriva o dal ramo "passa" del guardrail di uscita o dal digest di riserva
const ingresso = $input.first().json;
const digestFinale = ingresso.guardrailsInput !== undefined
  ? { digest: verifica.digest, origine: verifica.origine, guardrail_uscita: 'superato' }
  : { digest: ingresso.digest, origine: ingresso.origine, guardrail_uscita: ingresso.guardrail_uscita };

// --- schema fisso, controllato prima di scrivere
const OVERALL = ['positive', 'negative', 'mixed', 'neutral'];
const SENT = ['positive', 'negative', 'neutral'];
const idAspetti = new Set(tax.aspetti.map((a) => a.aspect));
const recensioni = analisi.map((r) => ({
  review_id: r.review_id,
  language: r.language,
  overall_sentiment: r.overall_sentiment,
  aspects: r.aspects.map((a) => ({ aspect: a.aspect, sentiment: a.sentiment })),
  needs_attention: r.needs_attention === true,
  attention_reason: r.needs_attention ? r.attention_reason : null,
}));
const errori = [];
const ids = new Set();
for (const r of recensioni) {
  if (typeof r.review_id !== 'string' || ids.has(r.review_id)) errori.push(`review_id non valido o ripetuto: ${r.review_id}`);
  ids.add(r.review_id);
  if (typeof r.language !== 'string' || !r.language) errori.push(`${r.review_id}: language mancante`);
  if (!OVERALL.includes(r.overall_sentiment)) errori.push(`${r.review_id}: overall_sentiment non ammesso`);
  for (const a of r.aspects) if (!idAspetti.has(a.aspect) || !SENT.includes(a.sentiment)) errori.push(`${r.review_id}: aspetto non valido ${JSON.stringify(a)}`);
  if (r.needs_attention && (typeof r.attention_reason !== 'string' || !r.attention_reason)) errori.push(`${r.review_id}: motivo mancante`);
}
if (recensioni.length !== pronte.length) errori.push(`recensioni in output ${recensioni.length} invece di ${pronte.length}`);
if (errori.length) throw new Error('Output non conforme allo schema:\n' + errori.slice(0, 20).join('\n'));

const aspetti = tax.aspetti.map((a) => ({ aspect: a.aspect, nome: a.nome, descrizione: a.descrizione, temi_raggruppati: a.temi_raggruppati }));

// temi giudicati che non rientrano in nessun aspetto: misura di quanto l'elenco copre
const nonMappati = {};
for (const r of analisi) for (const u of r.unmapped ?? []) nonMappati[u] = (nonMappati[u] ?? 0) + 1;
const conNonMappati = analisi.filter((r) => (r.unmapped ?? []).length > 0).length;

const oscurati = {};
for (const r of pronte) for (const [k, v] of Object.entries(r.dati_oscurati ?? {})) oscurati[k] = (oscurati[k] ?? 0) + v;

const esecuzione = {
  configurazione: { ...cfg, input_file: cfg.input_file },
  terminata_il: new Date().toISOString(),
  file: aggregazione.meta.righe_nel_file + ' righe lette da ' + cfg.input_file,
  anomalie_del_file: pronte[0]._file.anomalie,
  guardrail_ingresso: {
    dati_oscurati_prima_del_modello: oscurati,
    recensioni_con_dati_oscurati: pronte.filter((r) => Object.keys(r.dati_oscurati ?? {}).length).map((r) => r.review_id),
    recensioni_sospette_di_manipolazione: pronte.filter((r) => r.sospetta).map((r) => ({ review_id: r.review_id, controlli: r.guardrail_scattati })),
    errori_del_guardrail: pronte.filter((r) => r.guardrail_errore).map((r) => ({ review_id: r.review_id, errore: r.guardrail_errore })),
  },
  scoperta_aspetti: {
    origine: tax.origine_aspetti,
    versione: tax.versione_aspetti,
    recensioni_nel_campione: campione.length,
    campione: campione,
    temi_liberi_distinti: temi.temi.length,
    temi_piu_frequenti: temi.temi.slice(0, 40),
    copertura_temi_pct: tax.copertura_temi_pct,
    soglia_temi_frequenti: tax.soglia_temi_frequenti,
    giri_di_consolidamento: tax.giri_consolidamento,
    temi_tolti_perche_doppi: tax.temi_tolti_perche_doppi,
    temi_non_coperti: tax.temi_non_coperti,
  },
  analisi: {
    ...info_analisi,
    recensioni_con_temi_fuori_elenco: conNonMappati,
    temi_fuori_elenco_piu_frequenti: Object.entries(nonMappati).sort((a, b) => b[1] - a[1]).slice(0, 30).map(([tema, n]) => ({ tema, recensioni: n })),
  },
  digest: {
    origine: digestFinale.origine,
    guardrail_uscita: digestFinale.guardrail_uscita,
    verifica: verifica.verifica,
    testo_del_modello_scartato: verifica.ultimo_testo_modello,
  },
  fatti_dati_al_modello_per_il_digest: $('Fatti per il digest').first().json.fatti,
};

// --- tabelle CSV per strumenti di visualizzazione (Tableau, Excel, Power BI)
const campoCsv = (v) => {
  const s = v === null || v === undefined ? '' : String(v);
  return /[",\n\r;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const tabellaCsv = (colonne, righe) => [colonne.join(','), ...righe.map((r) => colonne.map((c) => campoCsv(r[c])).join(','))].join('\n') + '\n';
const nomeAspetto = Object.fromEntries(tax.aspetti.map((a) => [a.aspect, a.nome]));
// una riga per ogni coppia recensione-aspetto (le recensioni senza aspetti hanno una riga con aspetto vuoto)
const righeRecensioni = [];
for (const r of analisi) {
  const base = {
    review_id: r.review_id,
    data_pubblicazione: r.published_date ?? '',
    anno: r.anno ?? '',
    mese: r.published_date ? r.published_date.slice(0, 7) : '',
    voto: r.rating ?? '',
    lingua: r.language,
    piattaforma: r.piattaforma ?? '',
    versione: r.versione ?? '',
    sentiment_complessivo: r.overall_sentiment,
    da_segnalare: r.needs_attention,
    priorita: r.priorita ?? '',
    nei_conteggi: (r.stato === 'ok' || r.stato === 'ritentata') && !r.sospetta,
  };
  if (!r.aspects.length) righeRecensioni.push({ ...base, aspetto: '', nome_aspetto: '', sentiment_aspetto: '' });
  for (const a of r.aspects) righeRecensioni.push({ ...base, aspetto: a.aspect, nome_aspetto: nomeAspetto[a.aspect] ?? a.aspect, sentiment_aspetto: a.sentiment });
}
// una riga per ogni coppia periodo-aspetto, con i conteggi dell'aggregazione
const righePeriodi = aggregazione.periodi.flatMap((p) => Object.values(p.aspetti).map((a) => ({
  periodo: p.periodo,
  recensioni_del_periodo: p.recensioni,
  aspetto: a.aspect,
  nome_aspetto: a.nome,
  menzioni: a.menzioni,
  positive: a.positive,
  negative: a.negative,
  neutral: a.neutral,
  pct_recensioni_che_lo_apprezzano: a.pct_recensioni_che_lo_apprezzano,
  pct_recensioni_che_lo_criticano: a.pct_recensioni_che_lo_criticano,
})));

// --- registro del giro: token, costo e durata
// Token ESATTI per le chiamate fatte dal workflow (nodi HTTP e ritentativi nei nodi Code).
// Il guardrail con il modello lo esegue n8n al suo interno e non espone i token:
// per quello c'e' una STIMA dalla lunghezza dei testi (circa 4 caratteri per token).
const somma = (lista) => lista.reduce((t, u) => ({
  chiamate: t.chiamate + 1,
  token_input: t.token_input + (u?.prompt_tokens ?? 0),
  token_output: t.token_output + (u?.completion_tokens ?? 0),
}), { chiamate: 0, token_input: 0, token_output: 0 });
const usoDelNodo = (nomeNodo) => {
  try {
    return $(nomeNodo).all().map((i) => i.json?.usage).filter(Boolean);
  } catch (e) {
    return []; // nodo non eseguito (per esempio la scoperta con l'elenco fisso)
  }
};
const costo = (v) => Math.round(1e4 * ((v.token_input * cfg.prezzo_input_usd_per_milione + v.token_output * cfg.prezzo_output_usd_per_milione) / 1e6)) / 1e4;
const voci = {
  scoperta_temi_liberi: somma(usoDelNodo('LLM: temi liberi')),
  consolidamento_aspetti: somma([...usoDelNodo('LLM: consolida aspetti'), ...(tax.uso_token ?? [])]),
  analisi_recensioni: somma([...usoDelNodo('LLM: analisi recensioni'), ...(info_analisi.uso_token_ritentativi ?? [])]),
  digest: somma([...usoDelNodo('LLM: scrive digest'), ...(verifica.uso_token ?? [])]),
};
for (const v of Object.values(voci)) v.costo_usd = costo(v);
// stima per il guardrail con il modello: una chiamata per ogni recensione non gia' fermata dalle espressioni regolari
// (solo le recensioni controllate in questo giro: le altre hanno l'esito dalla memoria del guardrail)
const nelGuardrail = pronte.filter((r) => !r.guardrail_dalla_memoria && !(r.guardrail_scattati ?? []).some((c) => c !== 'jailbreak'));
const stimaGuardrail = {
  chiamate: nelGuardrail.length + 1,
  token_input: Math.round(nelGuardrail.reduce((t, r) => t + (1300 + r.title.length + r.text.length) / 4, 0) + (1300 + digestFinale.digest.length) / 4),
  token_output: (nelGuardrail.length + 1) * 30,
  nota: 'STIMA: token calcolati dalla lunghezza dei testi, n8n non li espone per i nodi Guardrails',
};
stimaGuardrail.costo_usd = costo(stimaGuardrail);
const misurato = Object.values(voci).reduce((t, v) => ({ token_input: t.token_input + v.token_input, token_output: t.token_output + v.token_output, costo_usd: t.costo_usd + v.costo_usd }), { token_input: 0, token_output: 0, costo_usd: 0 });
const fine = new Date();
const analisiMemoria = $('Valida e completa').first().json._memoria ?? null;
// memoria del guardrail «manipolazione»: esito di ogni recensione con la sua firma (gli errori tecnici no)
const guardrailMemoria = {
  versione_formato: 1,
  aggiornata_il: new Date().toISOString(),
  voci: Object.fromEntries(pronte.filter((r) => r.guardrail_firma && !r.guardrail_errore)
    .map((r) => [r.review_id, { firma: r.guardrail_firma, sospetta: !!r.sospetta, scattati: r.guardrail_scattati ?? [] }])),
};
const registroGiro = {
  inizio: cfg.started_at,
  fine: fine.toISOString(),
  durata_minuti: Math.round((fine - new Date(cfg.started_at)) / 6000) / 10,
  modello: cfg.model,
  prezzi_usd_per_milione_di_token: { input: cfg.prezzo_input_usd_per_milione, output: cfg.prezzo_output_usd_per_milione },
  recensioni: analisi.length,
  versione_aspetti: tax.versione_aspetti,
  // memoria: quante recensioni sono state riprese dal giro prima e quante mandate al modello
  analisi_riprese_dalla_memoria: info_analisi.dalla_memoria ?? 0,
  analisi_mandate_al_modello: info_analisi.analizzate_in_questo_giro ?? null,
  guardrail_ripresi_dalla_memoria: pronte.filter((r) => r.guardrail_dalla_memoria).length,
  guardrail_controllati_in_questo_giro: pronte.filter((r) => !r.guardrail_dalla_memoria).length,
  misurato_per_fase: voci,
  misurato_totale: { ...misurato, costo_usd: Math.round(1e4 * misurato.costo_usd) / 1e4 },
  guardrail_stimato: stimaGuardrail,
  costo_totale_usd_misurato_piu_stimato: Math.round(1e4 * (misurato.costo_usd + stimaGuardrail.costo_usd)) / 1e4,
  costo_per_1000_recensioni_usd: Math.round(1e4 * ((misurato.costo_usd + stimaGuardrail.costo_usd) / analisi.length) * 1000) / 1e4,
};
esecuzione.registro_giro = registroGiro;

const dir = cfg.output_dir;
const file = (nome, contenuto, mime) => ({
  json: { path: `${dir}/${nome}` },
  binary: { data: { data: Buffer.from(contenuto, 'utf8').toString('base64'), mimeType: mime, fileName: nome } },
});
let digest = digestFinale.digest;
if (!/^#\s/m.test(digest)) digest = '# Digest delle recensioni\n\n' + digest;

return [
  file('recensioni_analizzate.json', JSON.stringify(recensioni, null, 2), 'application/json'),
  file('recensioni_analizzate.jsonl', recensioni.map((r) => JSON.stringify(r)).join('\n') + '\n', 'application/x-ndjson'),
  file('aspetti.json', JSON.stringify({ versione: tax.versione_aspetti, origine: tax.origine_aspetti, aspetti }, null, 2), 'application/json'),
  file('aggregazione.json', JSON.stringify(aggregazione, null, 2), 'application/json'),
  file('digest.md', digest + '\n', 'text/markdown'),
  file('tabella_recensioni_aspetti.csv', tabellaCsv(['review_id', 'data_pubblicazione', 'anno', 'mese', 'voto', 'lingua', 'piattaforma', 'versione', 'sentiment_complessivo', 'da_segnalare', 'priorita', 'nei_conteggi', 'aspetto', 'nome_aspetto', 'sentiment_aspetto'], righeRecensioni), 'text/csv'),
  file('tabella_aspetti_per_periodo.csv', tabellaCsv(['periodo', 'recensioni_del_periodo', 'aspetto', 'nome_aspetto', 'menzioni', 'positive', 'negative', 'neutral', 'pct_recensioni_che_lo_apprezzano', 'pct_recensioni_che_lo_criticano'], righePeriodi), 'text/csv'),
  file('esecuzione.json', JSON.stringify(esecuzione, null, 2), 'application/json'),
  file('registro_giro.json', JSON.stringify(registroGiro, null, 2), 'application/json'),
  // memorie per il giro dopo (vedi «Prepara richieste analisi» e «Prepara controllo manipolazione»)
  ...(analisiMemoria ? [file('memoria_analisi.json', JSON.stringify(analisiMemoria), 'application/json')] : []),
  file('memoria_guardrail.json', JSON.stringify(guardrailMemoria), 'application/json'),
  // dettaglio per recensione, fuori dallo schema richiesto: serve a controllare e a verificare
  file('recensioni_diagnostica.jsonl', analisi.map((r, i) => JSON.stringify({
    review_id: r.review_id,
    stato: r.stato,
    sospetta: r.sospetta,
    guardrail_scattati: pronte[i].guardrail_scattati,
    dati_oscurati: pronte[i].dati_oscurati,
    priorita: r.priorita,
    segnalazioni: r.segnalazioni,
    temi_fuori_elenco: r.unmapped,
  })).join('\n') + '\n', 'application/x-ndjson'),
];

// PREPARA IL FILE EXCEL (recensioni_hotel.xlsx)
// Un solo file con piu' fogli, scritto accanto agli altri risultati: andamento mese per mese, confronti tra periodi,
// temi per mese, lingue, segnalazioni e una riga per recensione.
// Nessun numero nuovo: tutto viene dall'Aggregazione o e' un semplice conteggio delle analisi delle recensioni.
// I TESTI delle recensioni non ci sono: hanno la loro licenza e si scaricano a parte (vedi README); nel file ci sono
// solo le analisi e le brevi frasi citate come prova, come negli altri file dei risultati.
// Il file .xlsx e' costruito a mano (zip senza compressione + XML), perche' nel nodo Code non ci sono librerie esterne.
const cfg = $('Configurazione').first().json;
const A = $('Aggregazione').first().json.aggregazione;
const tax = $('Valida tassonomia').first().json;
const analisi = $('Valida e completa').all().map((i) => i.json);

const nomeAspetto = Object.fromEntries([...(A.aspetti ?? []).map((a) => [a.aspect, a.nome]), ...tax.aspetti.map((a) => [a.aspect, a.nome])]);
const SENT = { positive: 'positivo', negative: 'negativo', mixed: 'misto', neutral: 'neutro' };
const MISURA = { pct_recensioni_che_lo_criticano: '% recensioni che lo criticano', pct_recensioni_che_lo_apprezzano: '% recensioni che lo apprezzano' };
const pct = (a, b) => (b ? Math.round((1000 * a) / b) / 10 : null);
const valide = analisi.filter((r) => (r.stato === 'ok' || r.stato === 'ritentata') && !r.sospetta);

const fogli = [];
const R = A.periodi_di_calendario;
fogli.push({
  nome: 'Leggimi',
  colonne: ['foglio', 'che cosa contiene'],
  righe: [
    ['Mesi', 'Per ogni mese: recensioni, voto medio, sentiment e confronto con il mese prima.'],
    ['Confronti', 'Aspetti: ultimo periodo contro i precedenti (periodi di almeno ' + cfg.min_reviews_per_period + ' recensioni, come nel digest).'],
    ['Temi per mese', 'Per ogni mese e aspetto: quante recensioni lo apprezzano e quante lo criticano.'],
    ['Lingue', 'Recensioni per lingua, con la quota di negative.'],
    ['Segnalazioni', 'Le recensioni da guardare: categoria, priorità, che cosa dice chi ha scritto e la sua frase.'],
    ['Recensioni', 'Una riga per recensione: data, lingua, voto, sentiment, aspetti, segnalazioni. Senza testo: i testi si scaricano a parte (vedi README).'],
    ['', ''],
    ['Come leggere i confronti', '«oltre il rumore» = la differenza è troppo grande per essere un caso (test su due proporzioni con correzione per i confronti multipli). «entro il rumore» = può essere un caso. «pochi dati» = uno dei due mesi ha meno di 20 recensioni: si vedono i numeri ma non si dà un verdetto.'],
    ['p-value e verdetto', 'Un p-value sotto 0,05 può restare «entro il rumore»: con tanti confronti nella stessa tabella qualcuno risulta basso per caso, e la correzione alza la soglia (Benjamini-Hochberg, al massimo 10% di falsi allarmi attesi). Conta la colonna «confronto».'],
    ['Mesi incompleti', 'Il primo e l\'ultimo mese dell\'archivio possono essere coperti solo in parte: la colonna «nota» lo dice.'],
    ['Attenzione', 'Le recensioni sono affermazioni di chi le scrive, non fatti accertati.'],
    ['Regola dei mesi', R?.regola ?? ''],
    ['Giro del', new Date().toLocaleString('it-IT', { timeZone: 'Europe/Rome' })],
  ],
});

fogli.push({
  nome: 'Mesi',
  colonne: ['mese', 'nota', 'recensioni', 'voto medio', 'positive', 'negative', 'miste', 'neutre', '% negative', '% negative mese prima', 'differenza (punti)', 'confronto', 'p-value'],
  righe: (R?.mesi ?? []).flatMap((s) => s.periodi.map((p) => [
    p.periodo, p.dati_solo_dal ? `incompleto: dati solo dal ${p.dati_solo_dal}` : p.dati_fino_al ? `incompleto: dati fino al ${p.dati_fino_al}` : '',
    p.recensioni, p.voto_medio, p.positive, p.negative, p.miste, p.neutre,
    p.pct_negative, p.confronto?.pct_negative_prima ?? null, p.confronto?.differenza_punti ?? null, p.confronto?.esito ?? '', p.confronto?.p_value ?? null,
  ])),
});

fogli.push({
  nome: 'Confronti',
  colonne: ['confronto', 'aspetto', 'misura', 'valore nuovo', 'valore di confronto', 'differenza (punti)', 'p-value', 'esito'],
  righe: (A.andamento ?? []).map((x) => [`${x.ultimo_periodo} contro ${x.periodo_di_confronto}`, x.nome, MISURA[x.misura] ?? x.misura, x.valore_ultimo_periodo, x.valore_periodo_di_confronto, x.differenza_punti, x.p_value, x.significativo ? 'oltre il rumore' : 'entro il rumore']),
});

const temiMese = new Map(), recMese = new Map();
for (const r of valide) {
  if (!r.published_date) continue;
  const m = String(r.published_date).slice(0, 7);
  recMese.set(m, (recMese.get(m) ?? 0) + 1);
  for (const a of r.aspects ?? []) {
    const k = `${m}|${a.aspect}`;
    const x = temiMese.get(k) ?? { m, aspect: a.aspect, pos: 0, neg: 0 };
    if (a.sentiment === 'positive') x.pos++;
    if (a.sentiment === 'negative') x.neg++;
    temiMese.set(k, x);
  }
}
fogli.push({
  nome: 'Temi per mese',
  colonne: ['mese', 'aspetto', 'recensioni del mese', 'lo apprezzano', 'lo criticano', '% che lo criticano'],
  righe: [...temiMese.values()].sort((a, b) => a.m.localeCompare(b.m) || b.neg - a.neg)
    .map((x) => { const n = recMese.get(x.m); return [x.m, nomeAspetto[x.aspect] ?? x.aspect, n, x.pos, x.neg, pct(x.neg, n)]; }),
});

const perLingua = new Map();
for (const r of valide) { if (!perLingua.has(r.language)) perLingua.set(r.language, []); perLingua.get(r.language).push(r); }
fogli.push({
  nome: 'Lingue',
  colonne: ['lingua', 'recensioni', 'negative', '% negative'],
  righe: [...perLingua.entries()].map(([lg, l]) => { const neg = l.filter((r) => r.overall_sentiment === 'negative').length; return [lg === 'und' ? 'non riconosciuta' : lg, l.length, neg, pct(neg, l.length)]; })
    .sort((a, b) => b[1] - a[1]),
});

fogli.push({
  nome: 'Segnalazioni',
  colonne: ['data', 'voto', 'lingua', 'categoria', 'priorità', 'secondo chi ha scritto', 'frase della recensione', 'review_id'],
  righe: analisi.flatMap((r) => (r.segnalazioni ?? []).map((s) => [r.published_date ?? '', r.rating, r.language, s.nome_categoria, s.priorita, s.sintesi, s.evidenza, r.review_id]))
    .sort((a, b) => String(b[0]).localeCompare(String(a[0]))),
});

fogli.push({
  nome: 'Recensioni',
  colonne: ['data', 'lingua', 'voto', 'sentiment', 'aspetti (giudizio)', 'segnalazioni', 'nei conteggi', 'review_id'],
  righe: analisi.map((r) => [
    r.published_date ?? '', r.language === 'und' ? '' : r.language, r.rating, SENT[r.overall_sentiment] ?? r.overall_sentiment,
    (r.aspects ?? []).map((a) => `${nomeAspetto[a.aspect] ?? a.aspect}: ${SENT[a.sentiment] ?? a.sentiment}`).join('; '),
    [...new Set((r.segnalazioni ?? []).map((s) => s.nome_categoria))].join('; '),
    (r.stato === 'ok' || r.stato === 'ritentata') && !r.sospetta ? 'sì' : 'no',
    r.review_id,
  ]).sort((a, b) => String(b[0]).localeCompare(String(a[0]))),
});

// --- costruzione del file .xlsx
const xml = (s) => String(s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F￾￿]/g, '').slice(0, 32000)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const colonna = (i) => { let s = ''; i++; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
const cella = (v, rif, stile) => {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number' && Number.isFinite(v)) return `<c r="${rif}"${stile}><v>${v}</v></c>`;
  return `<c r="${rif}" t="inlineStr"${stile}><is><t xml:space="preserve">${xml(v)}</t></is></c>`;
};
const foglioXml = (f) => {
  const tutte = [f.colonne, ...f.righe];
  const larghezze = f.colonne.map((c, j) => Math.min(60, Math.max(10, ...tutte.slice(0, 200).map((r) => String(r[j] ?? '').length + 2))));
  const righe = tutte.map((r, i) => `<row r="${i + 1}">${r.map((v, j) => cella(v, `${colonna(j)}${i + 1}`, i === 0 ? ' s="1"' : '')).join('')}</row>`).join('');
  const ultima = `${colonna(f.colonne.length - 1)}${Math.max(1, tutte.length)}`;
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    + '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
    + '<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
    + `<cols>${larghezze.map((w, j) => `<col min="${j + 1}" max="${j + 1}" width="${w}" customWidth="1"/>`).join('')}</cols>`
    + `<sheetData>${righe}</sheetData>`
    + (f.righe.length ? `<autoFilter ref="A1:${ultima}"/>` : '')
    + '</worksheet>';
};
const file = {
  '[Content_Types].xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
    + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>'
    + '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
    + '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
    + fogli.map((_, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')
    + '</Types>',
  '_rels/.rels': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
    + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
  'xl/workbook.xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'
    + fogli.map((f, i) => `<sheet name="${xml(f.nome)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join('')
    + '</sheets>'
    + `<definedNames>${fogli.map((f, i) => (f.righe.length ? `<definedName name="_xlnm._FilterDatabase" localSheetId="${i}" hidden="1">'${xml(f.nome)}'!$A$1:$${colonna(f.colonne.length - 1)}$${f.righe.length + 1}</definedName>` : '')).join('')}</definedNames>`
    + '</workbook>',
  'xl/_rels/workbook.xml.rels': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
    + fogli.map((_, i) => `<Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join('')
    + `<Relationship Id="rId${fogli.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`,
  'xl/styles.xml': '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
    + '<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts>'
    + '<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>'
    + '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>'
    + '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
    + '<cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs>'
    + '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>',
};
fogli.forEach((f, i) => { file[`xl/worksheets/sheet${i + 1}.xml`] = foglioXml(f); });

// zip senza compressione (metodo «stored»), con CRC-32
const TABELLA_CRC = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = (buf) => { let c = 0xffffffff; for (const b of buf) c = TABELLA_CRC[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
const locali = [], centrali = [];
let posizione = 0;
for (const [nome, testo] of Object.entries(file)) {
  const n = Buffer.from(nome, 'utf8'), d = Buffer.from(testo, 'utf8'), crc = crc32(d);
  const loc = Buffer.alloc(30);
  loc.writeUInt32LE(0x04034b50, 0); loc.writeUInt16LE(20, 4); loc.writeUInt16LE(0x0800, 6); loc.writeUInt16LE(0, 8);
  loc.writeUInt16LE(0, 10); loc.writeUInt16LE(0x21, 12); loc.writeUInt32LE(crc, 14); loc.writeUInt32LE(d.length, 18); loc.writeUInt32LE(d.length, 22);
  loc.writeUInt16LE(n.length, 26); loc.writeUInt16LE(0, 28);
  const cen = Buffer.alloc(46);
  cen.writeUInt32LE(0x02014b50, 0); cen.writeUInt16LE(20, 4); cen.writeUInt16LE(20, 6); cen.writeUInt16LE(0x0800, 8); cen.writeUInt16LE(0, 10);
  cen.writeUInt16LE(0, 12); cen.writeUInt16LE(0x21, 14); cen.writeUInt32LE(crc, 16); cen.writeUInt32LE(d.length, 20); cen.writeUInt32LE(d.length, 24);
  cen.writeUInt16LE(n.length, 28); cen.writeUInt16LE(0, 30); cen.writeUInt16LE(0, 32); cen.writeUInt16LE(0, 34); cen.writeUInt16LE(0, 36);
  cen.writeUInt32LE(0, 38); cen.writeUInt32LE(posizione, 42);
  locali.push(loc, n, d); centrali.push(cen, n);
  posizione += loc.length + n.length + d.length;
}
const dirCentrale = Buffer.concat(centrali);
const fine = Buffer.alloc(22);
fine.writeUInt32LE(0x06054b50, 0); fine.writeUInt16LE(0, 4); fine.writeUInt16LE(0, 6);
fine.writeUInt16LE(Object.keys(file).length, 8); fine.writeUInt16LE(Object.keys(file).length, 10);
fine.writeUInt32LE(dirCentrale.length, 12); fine.writeUInt32LE(posizione, 16); fine.writeUInt16LE(0, 20);
const xlsx = Buffer.concat([...locali, dirCentrale, fine]);

return [{
  json: { path: `${cfg.output_dir}/recensioni_hotel.xlsx`, fogli: fogli.map((f) => ({ nome: f.nome, righe: f.righe.length })), byte: xlsx.length },
  binary: { data: { data: xlsx.toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: 'recensioni_hotel.xlsx' } },
}];
